//! A minimal SMT-LIB 2 front end — the QF_UF subset of `z3/src/cmd_context` +
//! `z3/src/parsers/smt2` (Z3 4.17.0, MIT).
//!
//! Supports: `set-logic`/`set-info`/`set-option` (ignored), `declare-sort`
//! (arity 0), `declare-fun`, `declare-const`, `assert`, `check-sat`,
//! `get-value`, `get-model`, `push`/`pop`/`reset`, and `exit`; the
//! `Bool`/`Int`/`Real` sorts, integer and decimal numerals, the core Boolean
//! operators, equality/`distinct`, `ite`, `let`, linear arithmetic
//! (`+ - * / <= < >= >`, `div`/`mod`/`abs`/`to_real`/`to_int`, with constant
//! folding), uninterpreted functions, arrays (`(Array I E)`, `select`, `store`,
//! `(as const …)`), and bit-vectors (`(_ BitVec n)`, `#x`/`#b`/`(_ bvN w)`
//! literals, `bvand/bvor/bvxor/bvnot`, `bvadd/bvsub/bvneg`,
//! `bvult/bvule/bvugt/bvuge`). Runs QF_UF / QF_LRA / QF_LIA / QF_A through
//! [`crate::smt::check_model`] and QF_BV through [`crate::smt::check_bv`]
//! (bit-blasting), and reports models via `get-value`/`get-model`.
//! Term-level (non-Boolean) `ite`s are lifted to fresh constants and the array
//! read-over-write axioms are instantiated before solving, so the theory reasons
//! about them exactly. (Nonlinear terms remain opaque — a known incompleteness
//! pending `nlsat`.)

use alloc::boxed::Box;
use alloc::collections::{BTreeMap, BTreeSet};
use alloc::string::{String, ToString};
use alloc::vec::Vec;

use puremp::{Int, Poly, Rational};

use crate::ast::AstId;
use crate::ast::arith::ArithOp;
use crate::ast::manager::AstManager;
use crate::rewriter::substitute;
use crate::smt::{
    Constraint, LinExpr, Model, OptOutcome, Rel, SmtResult, Value, arith_optimize, ast_to_lin,
    check_bv_model, check_bv_model_with_bools, check_model, feasible, linear_constraints, project,
    substitute_lin,
};

/// Optimization state carried between repeated `check-sat`s (z3's
/// `m_box_index` / `m_pareto` / `m_pareto1`); any change to the assertions or
/// objectives, or a `pop`, starts afresh.
#[derive(Default)]
enum OptIter {
    #[default]
    Fresh,
    /// `box`: the per-objective models, and the next one to report.
    Box {
        models: Vec<Option<Model>>,
        next: usize,
    },
    /// `pareto` over a single objective: the optimum was reported; next is `unsat`.
    Pareto1,
    /// `pareto`: the front enumeration so far.
    Pareto(ParetoState),
}

/// The `pareto` enumeration: objectives `(term, maximize?)` and the base
/// constraints — the soft penalty definitions plus a "not dominated by" block
/// per reported point.
struct ParetoState {
    objs: Vec<(AstId, bool)>,
    base: Vec<AstId>,
    /// Whether a front point has been reported (an `unsat` then means the
    /// front is exhausted, not that the constraints are).
    reported: bool,
}

/// An optimization objective, in declaration order (z3's `m_objectives`).
#[derive(Clone)]
enum Objective {
    /// `maximize`/`minimize` of a term, with its display text.
    Term {
        term: AstId,
        maximize: bool,
        text: String,
    },
    /// An `assert-soft` group (its `:id`, empty when none): penalty indicators
    /// with their weights. Minimizes the total weight of the violated softs.
    Soft {
        id: String,
        items: Vec<(AstId, i64)>,
    },
}

/// The exact optimum of a nonlinear real objective (see
/// `Context::nra_optimize`).
enum NraOpt {
    Infeasible,
    Unbounded,
    /// Attained at `value`, by the algebraic point `point` with the Boolean
    /// constants `bools`.
    Attained {
        value: crate::nlsat::realclosure::Alg,
        point: Vec<(AstId, crate::nlsat::realclosure::Alg)>,
        bools: Vec<(AstId, bool)>,
    },
    /// An open supremum (infimum), with z3's infinitesimal coefficient.
    Limit(crate::nlsat::realclosure::Alg, Rational),
}

impl NraOpt {
    fn value(&self) -> Option<&crate::nlsat::realclosure::Alg> {
        match self {
            NraOpt::Attained { value, .. } | NraOpt::Limit(value, _) => Some(value),
            _ => None,
        }
    }
}

/// The outcome of [`Context::mbqi_check`].
enum Mbqi {
    /// Every universal holds in the candidate model.
    Valid,
    /// A universal is refuted, but no instance could be built (its free
    /// functions have no fixed interpretation).
    Refuted,
    /// Counterexample instances to add to the ground goal.
    Refine(Vec<AstId>),
    /// Outside the checkable fragment.
    Unknown,
}

/// A ground value in an MBQI function table.
#[derive(Clone, PartialEq, Eq)]
enum MbqiVal {
    Bool(bool),
    Num(Rational, bool),
    Bv(Int, u32),
    /// An element of an uninterpreted sort: `(sort, class)`.
    Elem(AstId, usize),
}

/// State of [`Context::fmf_flattened`]: the domain elements, the one-hot
/// vectors of constants, the function tables and the side constraints.
#[derive(Default)]
struct FdEnc {
    /// Domain element → (its sort, its index).
    elem: BTreeMap<AstId, (AstId, usize)>,
    /// A domain-sorted constant → (its sort, its one-hot vector).
    consts: BTreeMap<AstId, (AstId, Vec<AstId>)>,
    /// (function, argument element indices) → its table entry.
    tables: BTreeMap<(AstId, Vec<usize>), FdEntry>,
    /// Exactly-one constraints of the one-hot vectors.
    side: Vec<AstId>,
    memo: BTreeMap<AstId, AstId>,
    dom_memo: BTreeMap<AstId, Vec<AstId>>,
}

/// A function-table entry of [`FdEnc`]: a one-hot vector over a domain sort,
/// or a fresh constant of another range sort.
enum FdEntry {
    Dom(AstId, Vec<AstId>),
    Val(AstId),
}

/// The model interpretation used by [`Context::mbqi_check`]: function tables
/// `decl → [(argument values, result)]`, a representative ground term per
/// element, and each uninterpreted sort's elements.
struct MbqiState {
    tables: BTreeMap<AstId, Vec<(Vec<MbqiVal>, MbqiVal)>>,
    reps: BTreeMap<(AstId, usize), AstId>,
    universe: BTreeMap<AstId, Vec<usize>>,
    /// The chosen default value per function (else the first entry's).
    defaults: BTreeMap<AstId, MbqiVal>,
}

/// A proven bracket `[lo, hi]` on an objective value (`None` = infinite).
type Bracket = (Option<Rational>, Option<Rational>);

/// The result of optimizing a real-valued objective.
enum RealOpt {
    /// A proven-exact attained optimum.
    Attained(Rational),
    /// A strict supremum/infimum (the bound value, not attained) and the
    /// coefficient of z3's infinitesimal in it (`r ∓ k·ε`).
    Supremum(Rational, Rational),
    /// Unbounded in the optimizing direction.
    Unbounded,
    /// Not determined exactly (non-linear or verification failed).
    Unknown,
}

/// An open optimum as z3 prints it: `r − k·ε` (maximize) or `r + k·ε`
/// (minimize), with `r` already rendered (`zero` drops it) and a unit `k`
/// elided: `(+ 2.0 (* (- 1.0) epsilon))`, `(+ (- 8.0) (* 2.0 epsilon))`,
/// `epsilon`.
fn render_eps_bound(r: &str, zero: bool, k: &Rational, maximize: bool) -> String {
    let unit = k.is_one();
    let eps = match (maximize, unit) {
        (true, _) => alloc::format!("(* (- {}) epsilon)", render_real(k)),
        (false, true) => "epsilon".to_string(),
        (false, false) => alloc::format!("(* {} epsilon)", render_real(k)),
    };
    if zero {
        eps
    } else {
        alloc::format!("(+ {r} {eps})")
    }
}

/// A non-integer rational as z3 prints it: `(/ p.0 q.0)`, negated outside
/// (`(- (/ 1.0 2.0))`).
fn render_fraction(r: &Rational) -> String {
    let (n, d) = (r.numerator(), r.denominator());
    if *n < Int::from(0) {
        alloc::format!("(- (/ {}.0 {d}.0))", n.abs())
    } else {
        alloc::format!("(/ {n}.0 {d}.0)")
    }
}

/// Render a rational as an SMT-LIB real term always keeping the fractional part
/// (`n.0`, `(- n.0)`, `(/ p.0 q.0)`), matching z3's epsilon expressions.
fn render_real(r: &Rational) -> String {
    let real = |n: &Int| -> String {
        if *n < Int::from(0) {
            alloc::format!("(- {}.0)", n.abs())
        } else {
            alloc::format!("{n}.0")
        }
    };
    if r.is_integer() {
        real(r.numerator())
    } else {
        render_fraction(r)
    }
}

/// A function interpretation as a finite table (see
/// `Context::fn_table_interps`): `(argument values, result)` entries and the
/// value elsewhere.
struct FnTable {
    entries: Vec<(Vec<AstId>, AstId)>,
    els: AstId,
}

/// A model value that depends on an irrational algebraic leaf (see
/// [`Model::alg_value`]), printed as z3 does: a real numeral, or `root-obj`
/// (a truncated decimal at `decimal` digits under `:pp.decimal`).
fn alg_model_value(
    m: &AstManager,
    model: &mut Model,
    id: AstId,
    decimal: Option<u32>,
) -> Option<String> {
    let a = model.alg_value(m, id)?;
    if a.is_rational() {
        return Some(render_real(a.interval().0));
    }
    if let Some(prec) = decimal {
        return Some(super::algebraic_pp::format_algebraic_decimal(&a, prec));
    }
    super::algebraic_pp::root_obj_string(&a)
}

/// An irrational objective value as z3's optimizer reports it: the
/// `(interval lo hi)` of its 12-decimal-digit bracket `lo < v < hi`.
fn render_alg_interval(a: &puremp::Algebraic) -> String {
    let scale = Rational::from_integer(Int::from(10).pow(12));
    let mut a = a.clone();
    let floor_of = |r: &Rational| r.mul(&scale).floor();
    loop {
        let (lo, hi) = a.interval();
        if floor_of(lo) == floor_of(hi) || a.is_rational() {
            break;
        }
        let w = hi.sub(lo).div(&Rational::from_integer(Int::from(2)));
        a.refine_below(&w);
    }
    let k = floor_of(a.interval().0);
    let lo = Rational::new(k.clone(), Int::from(10).pow(12));
    let hi = Rational::new(k.add(&Int::from(1)), Int::from(10).pow(12));
    alloc::format!(
        " (interval {} {})",
        render_rational(&lo),
        render_rational(&hi)
    )
}

/// The nlsat [`Alg`](crate::nlsat::realclosure::Alg) as a puremp
/// [`Algebraic`](puremp::Algebraic).
fn alg_to_algebraic(v: &crate::nlsat::realclosure::Alg) -> puremp::Algebraic {
    use crate::nlsat::realclosure::Alg;
    match v {
        Alg::Rational(r) => puremp::Algebraic::from_rational(r.clone()),
        Alg::Irrational { poly, lo, hi } => puremp::Algebraic::new(
            puremp::Poly::new(poly.coeffs().to_vec()),
            lo.clone(),
            hi.clone(),
        ),
    }
}

/// When every variable of `cons` and `obj` is pinned to a single real root
/// by its univariate constraints (an equality and bounds isolating one of its
/// roots): `Some(Some(point))` (indexed by variable) if every constraint holds
/// there, `Some(None)` if one fails; `None` when some variable is not so
/// determined.
fn determined_point(
    cons: &[(crate::math::polynomial::Polynomial, crate::nlsat::Rel)],
    obj: &crate::math::polynomial::Polynomial,
    nvars: usize,
) -> Option<Option<Vec<Option<crate::nlsat::realclosure::Alg>>>> {
    use crate::math::upoly::UPoly;
    use crate::nlsat::realclosure::{Alg, sign_at_point};
    let mut vars: BTreeSet<u32> = obj.vars().into_iter().collect();
    for (p, _) in cons {
        vars.extend(p.vars());
    }
    if vars.is_empty() || vars.iter().any(|&v| v as usize >= nvars) {
        return None;
    }
    let to_upoly = |p: &crate::math::polynomial::Polynomial, v: u32| -> Option<UPoly> {
        let d = p.degree_of(v);
        let mut cs = Vec::with_capacity(d as usize + 1);
        for k in 0..=d {
            cs.push(p.coeff_of_var(v, k).as_constant()?);
        }
        Some(UPoly::from_coeffs(cs))
    };
    let mut point: Vec<Option<Alg>> = alloc::vec![None; nvars];
    for &v in &vars {
        let uni: Vec<(UPoly, crate::nlsat::Rel)> = cons
            .iter()
            .filter(|(p, _)| p.vars() == alloc::vec![v])
            .filter_map(|(p, r)| Some((to_upoly(p, v)?, *r)))
            .collect();
        let eq = uni
            .iter()
            .find(|(q, r)| *r == crate::nlsat::Rel::Eq && !q.is_zero())?;
        let roots: Vec<Alg> = Alg::roots_of(&eq.0)
            .into_iter()
            .filter(|a| {
                uni.iter()
                    .all(|(q, r)| crate::nlsat::cad::rel_holds(a.sign_of(q), *r))
            })
            .collect();
        match roots.len() {
            0 => return Some(None),
            1 => point[v as usize] = roots.into_iter().next(),
            _ => return None,
        }
    }
    let full: Vec<Alg> = point
        .iter()
        .map(|v| {
            v.clone()
                .unwrap_or(Alg::Rational(Rational::from_integer(Int::from(0))))
        })
        .collect();
    // `c·(xᵢ − xⱼ)`: its sign is an exact comparison of the two coordinates
    // (the dominance constraints' shape; cheaper than a zero certification).
    let difference_sign = |p: &crate::math::polynomial::Polynomial| -> Option<i32> {
        let [(c1, m1), (c2, m2)] = p.terms() else {
            return None;
        };
        if m1.total_degree() != 1 || m2.total_degree() != 1 || *c1 != c2.neg() {
            return None;
        }
        let (i, j) = (m1.vars().next()?, m2.vars().next()?);
        let ord = full.get(i as usize)?.compare(full.get(j as usize)?);
        let s = match ord {
            core::cmp::Ordering::Less => -1,
            core::cmp::Ordering::Equal => 0,
            core::cmp::Ordering::Greater => 1,
        };
        Some(if c1.is_negative() { -s } else { s })
    };
    for (p, r) in cons {
        let sign = match difference_sign(p) {
            Some(s) => s,
            None => sign_at_point(p, &full)?,
        };
        if !crate::nlsat::cad::rel_holds(sign, *r) {
            return Some(None);
        }
    }
    Some(Some(point))
}

/// The value of `p` at the algebraic point `at` (every variable of `p`
/// assigned), by exact algebraic arithmetic; `None` when a variable is
/// unassigned.
fn eval_poly_alg(
    p: &crate::math::polynomial::Polynomial,
    at: &BTreeMap<u32, puremp::Algebraic>,
) -> Option<puremp::Algebraic> {
    let mut sum = puremp::Algebraic::from_rational(Rational::from_integer(Int::from(0)));
    for (c, mono) in p.terms() {
        let mut t = puremp::Algebraic::from_rational(c.clone());
        for v in mono.vars() {
            let x = at.get(&v)?;
            for _ in 0..mono.degree_of(v) {
                t = t.mul(x);
            }
        }
        sum = sum.add(&t);
    }
    Some(sum)
}

/// A puremp [`Algebraic`](puremp::Algebraic) as an nlsat
/// [`Alg`](crate::nlsat::realclosure::Alg): its squarefree defining polynomial
/// and an isolating interval refined until neither end is a root.
fn algebraic_to_alg(a: &puremp::Algebraic) -> Option<crate::nlsat::realclosure::Alg> {
    use crate::nlsat::realclosure::Alg;
    if a.is_rational() {
        return Some(Alg::Rational(a.interval().0.clone()));
    }
    let mut a = a.clone();
    let poly = a.defining_polynomial().clone();
    for _ in 0..256 {
        let (lo, hi) = a.interval();
        let (sl, sh) = (poly.eval(lo).signum(), poly.eval(hi).signum());
        if sl != 0 && sh != 0 && sl != sh {
            return Some(Alg::Irrational {
                poly: crate::math::upoly::UPoly::from_coeffs(poly.coeffs().to_vec()),
                lo: lo.clone(),
                hi: hi.clone(),
            });
        }
        let w = hi.sub(lo).div(&Rational::from_integer(Int::from(2)));
        a.refine_below(&w);
        if a.is_rational() {
            return Some(Alg::Rational(a.interval().0.clone()));
        }
    }
    None
}

/// A real algebraic number as z3 prints an objective value: a rational via
/// [`render_rational`], an irrational as its `(root-obj <minimal poly> <i>)`.
fn render_alg(v: &crate::nlsat::realclosure::Alg) -> String {
    let a = alg_to_algebraic(v);
    if a.is_rational() {
        return render_rational(a.interval().0);
    }
    super::algebraic_pp::root_obj_string(&a).unwrap_or_else(|| "unknown".to_string())
}

/// `v` as the real term of an `epsilon` bound: a rational keeps its `.0`
/// (`(+ 2.0 (* (- 1.0) epsilon))`), an irrational is a `root-obj`.
fn render_alg_real(v: &crate::nlsat::realclosure::Alg) -> String {
    let a = alg_to_algebraic(v);
    if a.is_rational() {
        return render_real(a.interval().0);
    }
    render_alg(v)
}

/// Render a rational as z3 prints an objective value: an integer as `n` /
/// `(- n)`, otherwise a fraction (see [`render_fraction`]).
fn render_rational(r: &Rational) -> String {
    if r.is_integer() {
        // z3 prints an integer-valued real without the fractional part.
        render_int(&r.numerator().clone())
    } else {
        render_fraction(r)
    }
}

/// The result of optimizing one objective.
enum OptResult {
    /// The proven optimal integer value.
    Optimum(Int),
    /// The objective is unbounded in the optimizing direction.
    Unbounded,
    /// Could not determine within budget.
    Unknown,
}

/// Substitute sort-macro parameters (atoms) by their argument s-expressions in
/// a `define-sort` body.
fn subst_sort(body: &SExpr, subst: &[(String, SExpr)]) -> SExpr {
    match body {
        SExpr::Atom(a) => subst
            .iter()
            .find(|(p, _)| p == a)
            .map(|(_, arg)| arg.clone())
            .unwrap_or_else(|| body.clone()),
        SExpr::List(l) => SExpr::List(l.iter().map(|e| subst_sort(e, subst)).collect()),
    }
}

/// `to_int(arg)` with integer-numeral summands pulled out of the floor:
/// `to_int(x + n) = n + to_int(x)` for integer `n` (matches z3's `mk_to_int_core`).
fn to_int_normal(m: &mut AstManager, arg: AstId) -> AstId {
    if let Some(v) = m.as_numeral(arg) {
        return m.mk_numeral(Rational::from_integer(v.floor()), true);
    }
    if m.arith_op(arg) == Some(ArithOp::Add) {
        let src = m.app_args(arg).to_vec();
        let mut int_sum = Rational::from_integer(puremp::Int::from(0));
        let mut rest: Vec<AstId> = Vec::new();
        for p in src {
            match m.as_numeral(p) {
                Some(v) if v.is_integer() => int_sum = &int_sum + &v,
                _ => rest.push(p),
            }
        }
        if !rest.is_empty() && !int_sum.is_zero() {
            let rest_t = if rest.len() == 1 {
                rest[0]
            } else {
                m.mk_add(&rest)
            };
            let ti = m.mk_to_int(rest_t);
            let n = m.mk_numeral(int_sum, true);
            return m.mk_add(&[n, ti]);
        }
    }
    m.mk_to_int(arg)
}

/// `to_real(arg)` distributed over `+` (`to_real` is a ring homomorphism), so
/// integer offsets align with a `to_int` pulled out of a sum.
fn to_real_normal(m: &mut AstManager, arg: AstId) -> AstId {
    if let Some(v) = m.as_numeral(arg) {
        return m.mk_numeral(v, false);
    }
    if m.arith_op(arg) == Some(ArithOp::Add) {
        let src = m.app_args(arg).to_vec();
        let mut parts = Vec::with_capacity(src.len());
        for p in src {
            match m.as_numeral(p) {
                Some(v) => parts.push(m.mk_numeral(v, false)),
                None => parts.push(m.mk_to_real(p)),
            }
        }
        return m.mk_add(&parts);
    }
    m.mk_to_real(arg)
}

/// Rewrite every bare reference to a sibling parametric datatype into its
/// implicit self-parameter application, e.g. in the legacy form
/// `(declare-datatypes (T) ((Tree … (children TreeList)) (TreeList …)))` the
/// bare `TreeList` denotes `(TreeList T)`. Applied recursively over a
/// constructor s-expression; leaves atoms that are not sibling names (type
/// parameters, field/constructor names) untouched.
fn apply_implicit_params(s: &SExpr, siblings: &[String], params: &[SExpr]) -> SExpr {
    match s {
        SExpr::Atom(a) if siblings.iter().any(|sib| sib == a) => {
            let mut v = alloc::vec![SExpr::Atom(a.clone())];
            v.extend(params.iter().cloned());
            SExpr::List(v)
        }
        SExpr::List(l) => SExpr::List(
            l.iter()
                .map(|e| apply_implicit_params(e, siblings, params))
                .collect(),
        ),
        other => other.clone(),
    }
}

/// The `(exponent bits, significand bits)` of a named floating-point format.
fn fp_format(name: &str) -> Option<(u32, u32)> {
    match name {
        "Float16" => Some((5, 11)),
        "Float32" => Some((8, 24)),
        "Float64" => Some((11, 53)),
        "Float128" => Some((15, 113)),
        _ => None,
    }
}

/// The canonical short spelling of a `RoundingMode` constant, so the long and
/// short names (e.g. `RNE` / `roundNearestTiesToEven`) intern to one constant.
fn rm_canonical(name: &str) -> &str {
    match name {
        "roundNearestTiesToEven" => "RNE",
        "roundNearestTiesToAway" => "RNA",
        "roundTowardPositive" => "RTP",
        "roundTowardNegative" => "RTN",
        "roundTowardZero" => "RTZ",
        other => other,
    }
}

/// The spelling z3 prints for a `RoundingMode` value.
fn rm_long_name(name: &str) -> &str {
    match name {
        "RNE" => "roundNearestTiesToEven",
        "RNA" => "roundNearestTiesToAway",
        "RTP" => "roundTowardPositive",
        "RTN" => "roundTowardNegative",
        "RTZ" => "roundTowardZero",
        other => other,
    }
}

/// Whether `name` is a `RoundingMode` constant.
fn is_rm_name(name: &str) -> bool {
    matches!(
        name,
        "RNE"
            | "RNA"
            | "RTP"
            | "RTN"
            | "RTZ"
            | "roundNearestTiesToEven"
            | "roundNearestTiesToAway"
            | "roundTowardPositive"
            | "roundTowardNegative"
            | "roundTowardZero"
    )
}

/// Left-fold a non-empty list of regexes with a binary combinator.
fn fold_regex(mut parts: Vec<Regex>, f: impl Fn(Regex, Regex) -> Regex) -> Regex {
    let mut acc = parts.remove(0);
    for p in parts {
        acc = f(acc, p);
    }
    acc
}

/// A Rust string from a slice of Unicode code points.
fn code_points_to_string(cps: &[u32]) -> String {
    cps.iter().filter_map(|&c| char::from_u32(c)).collect()
}

/// An atom of a word equation for the Nielsen transformation: either a concrete
/// character or a string variable (identified by a small stable id).
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
enum WAtom {
    Char(u32),
    Var(u32),
}

/// Fold a Boolean string predicate over literal operands' code points.
fn fold_string_pred(op: &str, parts: &[Vec<u32>]) -> bool {
    let (a, b) = (&parts[0], &parts[1]);
    match op {
        // (str.contains s sub): does `s` (=a) contain `sub` (=b)?
        "str.contains" => a.windows(b.len().max(1)).any(|w| w == b.as_slice()) || b.is_empty(),
        // (str.prefixof s t): is `s` (=a) a prefix of `t` (=b)?
        "str.prefixof" => a.len() <= b.len() && b[..a.len()] == a[..],
        // (str.suffixof s t): is `s` (=a) a suffix of `t` (=b)?
        "str.suffixof" => a.len() <= b.len() && b[b.len() - a.len()..] == a[..],
        // Lexicographic (code-point) order.
        "str.<" => a < b,
        "str.<=" => a <= b,
        _ => false,
    }
}

/// First index ≥ `from` at which `sub` occurs contiguously in `seq` (elements
/// compared by their hash-consed id). `None` if absent. Empty `sub` matches at
/// `from` (clamped to the length).
fn find_sub(seq: &[AstId], sub: &[AstId], from: usize) -> Option<usize> {
    if sub.is_empty() {
        return Some(from.min(seq.len()));
    }
    if sub.len() > seq.len() {
        return None;
    }
    (from..=seq.len() - sub.len()).find(|&i| seq[i..i + sub.len()] == sub[..])
}

/// Replace the first contiguous occurrence of `from` in `seq` with `to`.
fn replace_first_seq(seq: &[AstId], from: &[AstId], to: &[AstId]) -> Vec<AstId> {
    match find_sub(seq, from, 0) {
        Some(i) if !from.is_empty() => {
            let mut out = seq[..i].to_vec();
            out.extend_from_slice(to);
            out.extend_from_slice(&seq[i + from.len()..]);
            out
        }
        _ => seq.to_vec(),
    }
}

/// `2^w` as an arbitrary-precision integer.
fn pow2(w: u32) -> Int {
    let mut r = Int::from(1);
    let two = Int::from(2);
    for _ in 0..w {
        r = r.mul(&two);
    }
    r
}

/// `(str.replace_all s from to)` — replace every non-overlapping occurrence.
fn replace_all(s: &[u32], from: &[u32], to: &[u32]) -> String {
    if from.is_empty() || from.len() > s.len() {
        return code_points_to_string(s);
    }
    let mut out: Vec<u32> = Vec::new();
    let mut i = 0;
    while i < s.len() {
        if i + from.len() <= s.len() && s[i..i + from.len()] == from[..] {
            out.extend_from_slice(to);
            i += from.len();
        } else {
            out.push(s[i]);
            i += 1;
        }
    }
    code_points_to_string(&out)
}

/// `(str.replace s from to)` — replace the first occurrence of `from` in `s`.
fn replace_first(s: &[u32], from: &[u32], to: &[u32]) -> String {
    if from.is_empty() {
        let mut out = to.to_vec();
        out.extend_from_slice(s);
        return code_points_to_string(&out);
    }
    if from.len() <= s.len() {
        for i in 0..=s.len() - from.len() {
            if s[i..i + from.len()] == from[..] {
                let mut out = s[..i].to_vec();
                out.extend_from_slice(to);
                out.extend_from_slice(&s[i + from.len()..]);
                return code_points_to_string(&out);
            }
        }
    }
    code_points_to_string(s)
}

/// Interpret an unsigned `w`-bit value as a two's-complement signed integer.
fn to_signed(v: &Int, w: u32) -> Int {
    if w == 0 {
        return v.clone();
    }
    let half = Int::from(2).pow(u64::from(w - 1));
    if *v >= half {
        v.sub(&Int::from(2).pow(u64::from(w)))
    } else {
        v.clone()
    }
}

/// Render a `w`-bit field as z3's model printer does: `#x…` when the width is a
/// multiple of four, else `#b…`.
fn render_bv_field(v: u64, w: u32) -> String {
    if w > 0 && w.is_multiple_of(4) {
        let mut s = String::from("#x");
        for nib in (0..w / 4).rev() {
            let d = (v >> (nib * 4)) & 0xf;
            s.push(char::from_digit(d as u32, 16).unwrap());
        }
        s
    } else {
        let mut s = String::from("#b");
        for i in (0..w).rev() {
            s.push(if (v >> i) & 1 == 1 { '1' } else { '0' });
        }
        s
    }
}

/// Render a concrete `w`-bit vector value under the `pp.bv-neg` / `pp.bv-literals`
/// display options. With `pp.bv-neg`, a value whose top bit is set prints as
/// `(bvneg <two's-complement negation>)`; with `pp.bv-literals` off, a literal
/// prints as `(_ bv<decimal> w)` instead of `#x…`/`#b…`.
fn render_bv_pp(v: &Int, w: u32, bv_neg: bool, bv_literals: bool) -> String {
    let modulus = Int::from(1).mul_2k(u64::from(w)); // 2^w
    let half = Int::from(1).mul_2k(u64::from(w - 1)); // 2^(w-1)
    let negate = bv_neg && *v >= half;
    let shown = if negate { &modulus - v } else { v.clone() };
    let lit = if bv_literals {
        // `shown` fits in `w` bits; render the low 64 bits per nibble/bit.
        render_bv_field(shown.to_u64().unwrap_or(0), w)
    } else {
        alloc::format!("(_ bv{shown} {w})")
    };
    if negate {
        alloc::format!("(bvneg {lit})")
    } else {
        lit
    }
}

/// Render a floating-point bit pattern of format `(eb, sb)` the way z3's model
/// printer does: the special values as `(_ NaN eb sb)` / `(_ ±oo eb sb)` /
/// `(_ ±zero eb sb)`, and any finite value as `(fp #b<sign> <exp> <sig>)`.
fn render_fp(bits: u64, eb: u32, sb: u32) -> String {
    let mant = sb - 1;
    let sign = (bits >> (eb + mant)) & 1;
    let exp = (bits >> mant) & ((1u64 << eb) - 1);
    let sig = bits & ((1u64 << mant) - 1);
    let exp_ones = (1u64 << eb) - 1;
    if exp == exp_ones {
        return if sig == 0 {
            alloc::format!("(_ {} {eb} {sb})", if sign == 1 { "-oo" } else { "+oo" })
        } else {
            alloc::format!("(_ NaN {eb} {sb})")
        };
    }
    if exp == 0 && sig == 0 {
        return alloc::format!(
            "(_ {} {eb} {sb})",
            if sign == 1 { "-zero" } else { "+zero" }
        );
    }
    alloc::format!(
        "(fp #b{sign} {} {})",
        render_bv_field(exp, eb),
        render_bv_field(sig, mant)
    )
}

/// Render a dyadic rational `num / 2^k` as an exact decimal string (`"1.0"`,
/// `"1.5"`, …). Dyadic rationals terminate, so this is exact.
fn dyadic_decimal(num: &Int, k: u32) -> String {
    if k == 0 {
        return alloc::format!("{num}.0");
    }
    // num / 2^k = (num · 5^k) / 10^k.
    let mut five_k = Int::from(1);
    let five = Int::from(5);
    for _ in 0..k {
        five_k = five_k.mul(&five);
    }
    let scaled = num.mul(&five_k);
    let mut digits = alloc::format!("{scaled}");
    let k = k as usize;
    while digits.len() <= k {
        digits.insert(0, '0');
    }
    let point = digits.len() - k;
    let int_part = &digits[..point];
    let frac = digits[point..].trim_end_matches('0');
    let frac = if frac.is_empty() { "0" } else { frac };
    alloc::format!("{int_part}.{frac}")
}

/// Render a finite floating-point value in z3's `pp.fp_real_literals` form:
/// `((_ to_fp eb sb) RTZ <significand> <exponent>)`, value = significand·2^exp.
/// `None` for special values (NaN/±oo/±zero) and subnormals, which keep the
/// canonical form.
fn render_fp_real(bits: u64, eb: u32, sb: u32) -> Option<String> {
    let mant = sb - 1;
    let sign = (bits >> (eb + mant)) & 1;
    let exp = (bits >> mant) & ((1u64 << eb) - 1);
    let sig = bits & ((1u64 << mant) - 1);
    let exp_ones = (1u64 << eb) - 1;
    if exp == exp_ones || exp == 0 {
        return None; // special value or subnormal: leave to render_fp
    }
    let bias = (1i64 << (eb - 1)) - 1;
    // Normalized significand in [1,2): 1 + sig/2^mant; exponent = exp − bias.
    let num = Int::from((1u64 << mant) + sig);
    let e = exp as i64 - bias;
    let decimal = dyadic_decimal(&num, mant);
    let signed = if sign == 1 {
        alloc::format!("-{decimal}")
    } else {
        decimal
    };
    Some(alloc::format!("((_ to_fp {eb} {sb}) RTZ {signed} {e})"))
}

/// Render an integer as an SMT-LIB term (`n` or `(- n)`).
fn render_int(v: &Int) -> String {
    if *v < Int::from(0) {
        alloc::format!("(- {})", v.abs())
    } else {
        alloc::format!("{v}")
    }
}
use super::decl_table::DeclTable;
use crate::util::symbol::{Symbol, smt2_symbol};

/// Parse an SMT-LIB numeral: `42` → `(Int, 42)`, `1.5` → `(Real, 3/2)`.
fn parse_numeral(s: &str) -> Option<(Rational, bool)> {
    // z3 leniently accepts a negative literal such as `-1` or `-2.5` (strict
    // SMT-LIB writes these as `(- 1)`); accept it too for compatibility.
    if let Some(rest) = s.strip_prefix('-')
        && !rest.is_empty()
    {
        let (r, is_int) = parse_numeral(rest)?;
        return Some((r.neg(), is_int));
    }
    let is_digits = |t: &str| !t.is_empty() && t.bytes().all(|b| b.is_ascii_digit());
    if is_digits(s) {
        let i = Int::from_str_radix(s, 10).ok()?;
        return Some((Rational::from_integer(i), true));
    }
    let (int_part, frac_part) = s.split_once('.')?;
    let ip = if int_part.is_empty() { "0" } else { int_part };
    // z3 leniently accepts a trailing-dot decimal such as `0.` (= `0.0`); the
    // fractional part may be empty as long as the integer part is present.
    let frac_part = if frac_part.is_empty() && !int_part.is_empty() {
        "0"
    } else {
        frac_part
    };
    if !is_digits(ip) || !is_digits(frac_part) {
        return None;
    }
    // value = intpart.frac = (ip·10^k + frac) / 10^k
    let denom_str = alloc::format!("1{}", "0".repeat(frac_part.len()));
    let denom = Int::from_str_radix(&denom_str, 10).ok()?;
    let ip_i = Int::from_str_radix(ip, 10).ok()?;
    let frac_i = Int::from_str_radix(frac_part, 10).ok()?;
    let num = &(&ip_i * &denom) + &frac_i;
    Some((Rational::new(num, denom), false))
}

/// A rational from a small integer.
fn rat(n: i64) -> Rational {
    Rational::from_integer(Int::from(n))
}

/// The Boolean "the sign bit of the bit-vector `x` is set".
fn bv_sign(m: &mut AstManager, x: AstId) -> AstId {
    let n = m.bv_sort_width(m.get_sort(x)).expect("bv_sign: not a bv");
    let msb = m.mk_bv_extract(n - 1, n - 1, x);
    let one = m.mk_bv(1, 1);
    m.mk_eq(msb, one)
}

/// Whether `needle` occurs anywhere in the AST rooted at `hay` (memoised over
/// the hash-consed DAG so shared subterms are visited once).
fn ast_occurs(m: &AstManager, needle: AstId, hay: AstId, seen: &mut BTreeSet<AstId>) -> bool {
    if hay == needle {
        return true;
    }
    if !seen.insert(hay) {
        return false;
    }
    if m.is_app(hay) {
        let args: Vec<AstId> = m.app_args(hay).to_vec();
        return args.iter().any(|&c| ast_occurs(m, needle, c, seen));
    }
    false
}

/// Whether `body` contains a partial arithmetic operator (`div`/`mod`/`rem`/`/`).
/// These are unspecified on a zero divisor — effectively uninterpreted there —
/// so a closed universal over them can't be soundly decided by pinning a value.
fn contains_partial_arith(m: &AstManager, body: AstId, seen: &mut BTreeSet<AstId>) -> bool {
    if !seen.insert(body) {
        return false;
    }
    if matches!(
        m.arith_op(body),
        Some(ArithOp::Div | ArithOp::Idiv | ArithOp::Mod | ArithOp::Rem)
    ) {
        return true;
    }
    if !m.is_app(body) {
        return false;
    }
    let args = m.app_args(body).to_vec();
    args.iter().any(|&c| contains_partial_arith(m, c, seen))
}

/// Whether every uninterpreted leaf of `body` is one of `vars` — i.e. `body`
/// has no free symbol other than the given (bound-variable) constants. A free
/// uninterpreted *function* application (arity ≥ 1) always disqualifies it.
fn is_closed_over(
    m: &AstManager,
    body: AstId,
    vars: &BTreeSet<AstId>,
    seen: &mut BTreeSet<AstId>,
) -> bool {
    if !seen.insert(body) {
        return true;
    }
    if !m.is_app(body) {
        return true;
    }
    let (fam, nargs) = {
        let a = m.app(body).expect("is_app");
        (m.func_decl(a.decl).map(|d| d.info.family_id), a.args.len())
    };
    if fam == Some(crate::ast::NULL_FAMILY_ID) {
        // an uninterpreted symbol: a bound-var const is fine, anything else free
        if nargs == 0 {
            if !vars.contains(&body) {
                return false;
            }
        } else {
            return false;
        }
    }
    let args = m.app_args(body).to_vec();
    args.iter().all(|&c| is_closed_over(m, c, vars, seen))
}

/// Whether `id` is syntactically non-negative because it is the canonical
/// integer/real `abs` expansion `(ite (>= t 0) t (- t))`. Used to fold
/// `abs(abs t) = abs t` so idempotent absolute values are recognised equal.
fn is_abs_nonneg(m: &AstManager, id: AstId) -> bool {
    if !m.is_ite(id) {
        return false;
    }
    let a = m.app_args(id);
    if a.len() != 3 {
        return false;
    }
    let (then, els) = (a[1], a[2]);
    // condition is `(>= then 0)`
    if m.arith_op(a[0]) != Some(ArithOp::Ge) {
        return false;
    }
    let c = m.app_args(a[0]);
    if c.len() != 2 || c[0] != then || m.as_numeral(c[1]).map(|r| r.is_zero()) != Some(true) {
        return false;
    }
    // else branch is `(- then)`
    let e = m.app_args(els);
    m.arith_op(els) == Some(ArithOp::Uminus) && e.len() == 1 && e[0] == then
}

/// `|x|` as a bit-vector: `ite(sign, -x, x)`.
fn bv_abs(m: &mut AstManager, x: AstId) -> AstId {
    let s = bv_sign(m, x);
    let neg = m.mk_bvneg(x);
    m.mk_ite(s, neg, x)
}

/// `(bvsdiv s t)` — signed division (round toward zero), per the SMT-LIB theory
/// definition in terms of `bvudiv`/`bvneg` and the operand signs.
/// Zero-extend `a` by `k` high bits.
fn zero_ext(m: &mut AstManager, a: AstId, k: u32) -> AstId {
    if k == 0 {
        return a;
    }
    let z = m.mk_bv(0, k);
    m.mk_bv_concat(z, a)
}

/// Sign-extend `a` (width `w`) by `k` high bits.
fn sign_ext(m: &mut AstManager, a: AstId, k: u32, w: u32) -> AstId {
    if k == 0 {
        return a;
    }
    let sign = m.mk_bv_extract(w - 1, w - 1, a);
    let mut top = sign;
    for _ in 1..k {
        top = m.mk_bv_concat(top, sign);
    }
    m.mk_bv_concat(top, a)
}

/// The most-significant (sign) bit of `a` equals `#b1`.
fn msb_set(m: &mut AstManager, a: AstId, w: u32) -> AstId {
    let s = m.mk_bv_extract(w - 1, w - 1, a);
    let one = m.mk_bv(1, 1);
    m.mk_eq(s, one)
}

/// Bit-vector overflow predicates (Bool), matching z3's `bvXovo` operators.
fn bv_overflow(m: &mut AstManager, op: &str, a: AstId, b: AstId, w: u32) -> AstId {
    match op {
        // Unsigned add: carry out of the (w+1)-bit sum.
        "bvuaddo" => {
            let (za, zb) = (zero_ext(m, a, 1), zero_ext(m, b, 1));
            let s = m.mk_bvadd(za, zb);
            let top = m.mk_bv_extract(w, w, s);
            let one = m.mk_bv(1, 1);
            m.mk_eq(top, one)
        }
        // Signed add: operands same sign, result differs.
        "bvsaddo" => {
            let (sa, sb) = (msb_set(m, a, w), msb_set(m, b, w));
            let sum = m.mk_bvadd(a, b);
            let ssum = msb_set(m, sum, w);
            let same = m.mk_eq(sa, sb);
            let ne = m.mk_eq(ssum, sa);
            let ne = m.mk_not(ne);
            m.mk_and(&[same, ne])
        }
        // Unsigned subtract: borrow, i.e. a <u b.
        "bvusubo" => m.mk_bvult(a, b),
        // Signed subtract: operands differ in sign, result differs from a.
        "bvssubo" => {
            let (sa, sb) = (msb_set(m, a, w), msb_set(m, b, w));
            let diff = m.mk_bvsub(a, b);
            let sd = msb_set(m, diff, w);
            let opp = m.mk_eq(sa, sb);
            let opp = m.mk_not(opp);
            let ne = m.mk_eq(sd, sa);
            let ne = m.mk_not(ne);
            m.mk_and(&[opp, ne])
        }
        // Signed negation: a is the minimum value (100…0).
        "bvnego" => {
            let lo = m.mk_bv(0, w - 1);
            let hi = m.mk_bv(1, 1);
            let min = m.mk_bv_concat(hi, lo);
            m.mk_eq(a, min)
        }
        // Unsigned multiply: high `w` bits of the 2w-bit product are nonzero.
        "bvumulo" => {
            let (za, zb) = (zero_ext(m, a, w), zero_ext(m, b, w));
            let p = m.mk_bvmul(za, zb);
            let hi = m.mk_bv_extract(2 * w - 1, w, p);
            let zero = m.mk_bv(0, w);
            let eqz = m.mk_eq(hi, zero);
            m.mk_not(eqz)
        }
        // Signed multiply: the top w+1 bits of the 2w-bit product are not all
        // equal (not a clean sign extension of the low w bits).
        "bvsmulo" => {
            let (sa2, sb2) = (sign_ext(m, a, w, w), sign_ext(m, b, w, w));
            let p = m.mk_bvmul(sa2, sb2);
            let hi = m.mk_bv_extract(2 * w - 1, w - 1, p); // w+1 bits
            let zero = m.mk_bv(0, w + 1);
            let ones = m.mk_bvnot(zero);
            let is0 = m.mk_eq(hi, zero);
            let is1 = m.mk_eq(hi, ones);
            let clean = m.mk_or(&[is0, is1]);
            m.mk_not(clean)
        }
        // Signed division: only INT_MIN / -1 overflows.
        "bvsdivo" => {
            let lo = m.mk_bv(0, w - 1);
            let hi = m.mk_bv(1, 1);
            let min = m.mk_bv_concat(hi, lo);
            let a_min = m.mk_eq(a, min);
            let zero = m.mk_bv(0, w);
            let neg1 = m.mk_bvnot(zero);
            let b_neg1 = m.mk_eq(b, neg1);
            m.mk_and(&[a_min, b_neg1])
        }
        _ => m.mk_false(),
    }
}

fn bv_sdiv(m: &mut AstManager, s: AstId, t: AstId) -> AstId {
    let (ss, st) = (bv_sign(m, s), bv_sign(m, t));
    let (ns, nt) = (m.mk_bvneg(s), m.mk_bvneg(t));
    let d_pp = m.mk_bvudiv(s, t); // ¬ss ∧ ¬st
    let u_np = m.mk_bvudiv(ns, t);
    let d_np = m.mk_bvneg(u_np); // ss ∧ ¬st
    let u_pn = m.mk_bvudiv(s, nt);
    let d_pn = m.mk_bvneg(u_pn); // ¬ss ∧ st
    let d_nn = m.mk_bvudiv(ns, nt); // ss ∧ st
    let ss_true = m.mk_ite(st, d_nn, d_np);
    let ss_false = m.mk_ite(st, d_pn, d_pp);
    m.mk_ite(ss, ss_true, ss_false)
}

/// `(bvsrem s t)` — signed remainder (sign follows the dividend `s`).
fn bv_srem(m: &mut AstManager, s: AstId, t: AstId) -> AstId {
    let (ss, st) = (bv_sign(m, s), bv_sign(m, t));
    let (ns, nt) = (m.mk_bvneg(s), m.mk_bvneg(t));
    let r_pp = m.mk_bvurem(s, t);
    let u_np = m.mk_bvurem(ns, t);
    let r_np = m.mk_bvneg(u_np);
    let r_pn = m.mk_bvurem(s, nt);
    let u_nn = m.mk_bvurem(ns, nt);
    let r_nn = m.mk_bvneg(u_nn);
    let ss_true = m.mk_ite(st, r_nn, r_np);
    let ss_false = m.mk_ite(st, r_pn, r_pp);
    m.mk_ite(ss, ss_true, ss_false)
}

/// `(bvsmod s t)` — signed modulo (sign follows the divisor `t`).
fn bv_smod(m: &mut AstManager, s: AstId, t: AstId) -> AstId {
    let (ss, st) = (bv_sign(m, s), bv_sign(m, t));
    let abs_s = bv_abs(m, s);
    let abs_t = bv_abs(m, t);
    let u = m.mk_bvurem(abs_s, abs_t);
    let neg_u = m.mk_bvneg(u);
    let n = m.bv_sort_width(m.get_sort(s)).expect("bvsmod: not a bv");
    let zero = m.mk_bv(0, n);
    let u_zero = m.mk_eq(u, zero);
    let neg_u_plus_t = m.mk_bvadd(neg_u, t); // ss ∧ ¬st
    let u_plus_t = m.mk_bvadd(u, t); // ¬ss ∧ st
    let ss_true = m.mk_ite(st, neg_u, neg_u_plus_t);
    let ss_false = m.mk_ite(st, u_plus_t, u);
    let nonzero = m.mk_ite(ss, ss_true, ss_false);
    m.mk_ite(u_zero, u, nonzero)
}

/// Parse a bit-vector literal `#x1a` (hex, 4 bits/digit) or `#b101` (binary,
/// 1 bit/digit) into `(value, width)`.
fn parse_bv_literal(s: &str) -> Option<(Int, u32)> {
    if let Some(hex) = s.strip_prefix("#x") {
        if hex.is_empty() || !hex.bytes().all(|b| b.is_ascii_hexdigit()) {
            return None;
        }
        Some((Int::from_str_radix(hex, 16).ok()?, hex.len() as u32 * 4))
    } else if let Some(bin) = s.strip_prefix("#b") {
        if bin.is_empty() || !bin.bytes().all(|b| b == b'0' || b == b'1') {
            return None;
        }
        Some((Int::from_str_radix(bin, 2).ok()?, bin.len() as u32))
    } else {
        None
    }
}

/// The rational values of `args` if *every* one is a numeral, else `None`.
fn all_numerals(m: &AstManager, args: &[AstId]) -> Option<Vec<Rational>> {
    args.iter().map(|&a| m.as_numeral(a)).collect()
}

/// Are all of `args` integer-sorted (so a folded result stays `Int`)?
fn all_int(m: &AstManager, args: &[AstId]) -> bool {
    args.iter().all(|&a| m.is_int_sort(m.get_sort(a)))
}

/// Coerce a mixed Int/Real operand list of a numeric operator to all-Real, as
/// z3 does (an integer numeral or term in a real context is promoted). Without
/// this an n-ary product/sum inherits the sort of its *first* operand, so
/// `(* 17 3.5 r)` (integer literal first) would be built `Int`-sorted and fed to
/// integer reasoning — a fuzz/regression unsoundness (issue 3154). No-op unless
/// the list genuinely mixes an `Int`-sorted and a `Real`-sorted operand.
fn coerce_mixed_reals(m: &mut AstManager, args: &mut [AstId]) {
    let has_real = args
        .iter()
        .any(|&a| m.is_arith_sort(m.get_sort(a)) && !m.is_int_sort(m.get_sort(a)));
    let has_int = args.iter().any(|&a| m.is_int_sort(m.get_sort(a)));
    if !(has_real && has_int) {
        return;
    }
    for a in args.iter_mut() {
        if m.is_int_sort(m.get_sort(*a)) {
            *a = match m.as_numeral(*a) {
                Some(v) => m.mk_numeral(v, false),
                None => m.mk_to_real(*a),
            };
        }
    }
}

/// If both terms are integer numerals, return them as [`Int`]s.
fn int_pair(m: &AstManager, a: AstId, b: AstId) -> Option<(Int, Int)> {
    let ai = m.as_numeral(a)?.to_integer()?;
    let bi = m.as_numeral(b)?.to_integer()?;
    Some((ai, bi))
}

/// Euclidean division and remainder (SMT-LIB `div`/`mod`): `a = b·q + r` with
/// `0 ≤ r < |b|`. `b` must be non-zero.
fn euclid_div_mod(a: &Int, b: &Int) -> (Int, Int) {
    let (q, r) = a.div_rem_trunc(b); // truncated: r has the sign of a
    if r < Int::from(0) {
        if *b > Int::from(0) {
            (&q - &Int::from(1), &r + b)
        } else {
            (&q + &Int::from(1), &r - b)
        }
    } else {
        (q, r)
    }
}

/// The SMT-LIB response word for a verdict.
fn verdict_word(res: SmtResult) -> &'static str {
    match res {
        SmtResult::Sat => "sat",
        SmtResult::Unsat => "unsat",
        SmtResult::Unknown => "unknown",
    }
}

/// z3's maximum Unicode code point for the string theory. A `\u{…}` escape whose
/// value exceeds this is *not* recognised as an escape (the backslash is literal),
/// matching z3.
const SMT_MAX_CODE_POINT: u32 = 0x2FFFF;

/// Decode an SMT-LIB Unicode escape starting at `s[0] == '\\'`: either `\uXXXX`
/// (exactly four hex digits) or `\u{X…}` (one or more hex digits, value ≤
/// [`SMT_MAX_CODE_POINT`]). Returns the decoded scalar and the number of `char`s
/// consumed, or `None` if `s` is not a valid escape (the caller then treats the
/// backslash literally). Surrogate code points, which cannot be held in a Rust
/// `char`, are treated as non-escapes.
fn decode_unicode_escape(s: &[char]) -> Option<(char, usize)> {
    if s.first() != Some(&'\\') || s.get(1) != Some(&'u') {
        return None;
    }
    if s.get(2) == Some(&'{') {
        let mut j = 3;
        let mut val: u32 = 0;
        let mut n = 0;
        while j < s.len() && s[j] != '}' {
            let d = s[j].to_digit(16)?;
            val = val.checked_mul(16)?.checked_add(d)?;
            if val > SMT_MAX_CODE_POINT {
                return None;
            }
            n += 1;
            j += 1;
        }
        if n == 0 || j >= s.len() || s[j] != '}' {
            return None;
        }
        Some((char::from_u32(val)?, j + 1))
    } else {
        if s.len() < 6 {
            return None;
        }
        let mut val: u32 = 0;
        for &c in &s[2..6] {
            val = val * 16 + c.to_digit(16)?;
        }
        Some((char::from_u32(val)?, 6))
    }
}

/// The content of an SMT-LIB string literal token (`"…"`): surrounding quotes
/// removed, doubled `""` collapsed to a single quote, and `\uXXXX` / `\u{X…}`
/// Unicode escapes decoded. Non-string tokens are returned unchanged.
fn unquote_string(tok: &str) -> String {
    if !(tok.len() >= 2 && tok.starts_with('"') && tok.ends_with('"')) {
        return tok.to_string();
    }
    let inner: Vec<char> = tok[1..tok.len() - 1].chars().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < inner.len() {
        let c = inner[i];
        if c == '"' && inner.get(i + 1) == Some(&'"') {
            out.push('"');
            i += 2;
            continue;
        }
        if c == '\\'
            && let Some((ch, adv)) = decode_unicode_escape(&inner[i..])
        {
            out.push(ch);
            i += adv;
            continue;
        }
        out.push(c);
        i += 1;
    }
    out
}

/// Render code points as an SMT-LIB string literal (with surrounding quotes),
/// escaping exactly as z3 does: a `"` becomes `""`; a printable ASCII character
/// is emitted verbatim (a backslash only escaped to `\u{5c}` when the next
/// character is `u`, to avoid forging an escape on re-read); anything else
/// becomes `\u{hex}`. The result round-trips through [`unquote_string`].
fn smt_string_literal(cps: &[u32]) -> String {
    let mut out = String::from("\"");
    for (i, &c) in cps.iter().enumerate() {
        match c {
            0x22 => out.push_str("\"\""),
            0x5c if cps.get(i + 1) == Some(&0x75) => out.push_str("\\u{5c}"),
            0x20..=0x7e => out.push(char::from_u32(c).unwrap()),
            _ => out.push_str(&alloc::format!("\\u{{{c:x}}}")),
        }
    }
    out.push('"');
    out
}

/// z3's warnings for the attributes it does not know in the `(! term attr…)`
/// annotations of a command, in order (`smt2parser::consume_attributes`):
/// each unknown keyword is reported and skips one value. A keyword glued to a
/// quoted symbol (`:||`) is a keyword followed by that symbol, as z3's scanner
/// reads it.
fn unknown_attribute_warnings(form: &SExpr) -> Vec<String> {
    const KNOWN: [&str; 8] = [
        ":named",
        ":pattern",
        ":no-pattern",
        ":weight",
        ":qid",
        ":skolemid",
        ":lblpos",
        ":lblneg",
    ];
    /// The scanner tokens of an atom our tokenizer kept whole.
    fn split(a: &str) -> Vec<String> {
        if !a.starts_with(':') || !a.contains('|') {
            return alloc::vec![a.to_string()];
        }
        let cs: Vec<char> = a.chars().collect();
        let mut out = Vec::new();
        let mut i = 0;
        while i < cs.len() {
            let mut j = i + 1;
            if cs[i] == '|' {
                while j < cs.len() && cs[j] != '|' {
                    j += 1;
                }
                j = (j + 1).min(cs.len());
            } else {
                while j < cs.len() && cs[j] != ':' && cs[j] != '|' {
                    j += 1;
                }
            }
            out.push(cs[i..j].iter().collect());
            i = j;
        }
        out
    }
    fn walk(e: &SExpr, out: &mut Vec<String>) {
        let SExpr::List(l) = e else { return };
        if l.len() >= 2 && matches!(&l[0], SExpr::Atom(h) if h == "!") {
            // `None` stands for a list value.
            let mut items: Vec<Option<String>> = Vec::new();
            for x in &l[2..] {
                match x {
                    SExpr::Atom(a) => items.extend(split(a).into_iter().map(Some)),
                    SExpr::List(_) => items.push(None),
                }
            }
            let mut i = 0;
            while let Some(Some(k)) = items.get(i) {
                if !k.starts_with(':') {
                    break;
                }
                if !KNOWN.contains(&k.as_str()) {
                    out.push(alloc::format!("WARNING: unknown attribute {k}"));
                }
                i += 2;
            }
        }
        for x in l {
            walk(x, out);
        }
    }
    let mut out = Vec::new();
    if let SExpr::List(l) = form
        && !matches!(l.first(), Some(SExpr::Atom(h)) if h == "set-info" || h == "set-option")
    {
        walk(form, &mut out);
    }
    out
}

/// The `:named` label of an assertion written `(! term :named name …)`, if any.
fn named_label(s: &SExpr) -> Option<String> {
    let SExpr::List(l) = s else { return None };
    if l.first().and_then(|h| match h {
        SExpr::Atom(a) => Some(a.as_str()),
        _ => None,
    }) != Some("!")
    {
        return None;
    }
    // Scan for `:named <name>`.
    let mut it = l[1..].iter();
    while let Some(part) = it.next() {
        if let SExpr::Atom(k) = part
            && k == ":named"
            && let Some(SExpr::Atom(name)) = it.next()
        {
            return Some(name.clone());
        }
    }
    None
}

/// Working state for [`Context::lift_terms`]: the defining constraints collected
/// so far, a memo of already-lifted subterms, and a memo of `(a, divisor)` pairs
/// sharing a `(quotient, remainder)`.
struct LiftCtx {
    defs: Vec<AstId>,
    cache: BTreeMap<AstId, AstId>,
    dm: BTreeMap<(AstId, AstId), (AstId, AstId)>,
    /// Memo of `(to_int a)` arguments → their integer result constant.
    toint: BTreeMap<AstId, AstId>,
    /// Memo of `(/ a b)` terms (symbolic divisor) → their quotient constant.
    rdiv: BTreeMap<AstId, AstId>,
    /// Dividends occurring in ≥2 distinct `div`/`mod` terms — the only case where
    /// two zero-divisor results can coincide, so only these get `div0`/`mod0`
    /// consistency axioms (a lone zero-divisor term is genuinely free, and
    /// emitting the axiom for every term needlessly bloats div/mod-heavy goals).
    coincident_dividends: BTreeSet<AstId>,
    /// Memo of `(^ b 1/2)` bases → their square-root constant.
    sqrt: BTreeMap<AstId, AstId>,
    /// The goal's top-level linear conjuncts (for entailed side conditions).
    lin_facts: Vec<Constraint>,
}

/// An s-expression.
#[derive(Clone, Debug, PartialEq, Eq)]
enum SExpr {
    Atom(String),
    List(Vec<SExpr>),
}

/// Run an SMT-LIB `script`, returning one response line per `check-sat`
/// (`"sat"`, `"unsat"`, or `"unknown"`). Accepts both SMT-LIB 2 command scripts
/// and the older SMT-LIB 1.2 `(benchmark …)` format.
pub fn run(script: &str) -> Result<Vec<String>, String> {
    match run_partial(script) {
        (out, None) => Ok(out),
        (_, Some(e)) => Err(e),
    }
}

/// [`run`], keeping the responses printed before a fatal error: the
/// responses so far, and the error that stopped the script (if any).
pub fn run_partial(script: &str) -> (Vec<String>, Option<String>) {
    let mut out = Vec::new();
    match run_into(script, &mut out) {
        Ok(()) => (out, None),
        Err(e) => (out, Some(e)),
    }
}

fn run_into(script: &str, out: &mut Vec<String>) -> Result<(), String> {
    let (toks, positions) = tokenize(script);
    // SMT-LIB 1.2: a single top-level (benchmark …) form.
    if toks.first().map(String::as_str) == Some("(")
        && toks.get(1).map(String::as_str) == Some("benchmark")
    {
        let forms = parse(script)?;
        if let [SExpr::List(l)] = forms.as_slice() {
            out.extend(run_v1(l)?);
            return Ok(());
        }
    }
    let mut ctx = Context::new();
    let mut p = 0usize;
    while p < toks.len() {
        // Every top-level command starts with `(`; anything else is a syntax
        // error, reported at its position, after which z3 resyncs to the next `(`.
        if toks[p] != "(" {
            let (l, c) = positions[p];
            out.push(alloc::format!(
                "(error \"line {l} column {c}: invalid command, '(' expected\")"
            ));
            while p < toks.len() && toks[p] != "(" {
                p += 1;
            }
            continue;
        }
        let cmd_start = p;
        let form = match parse_one(&toks, &positions, &mut p) {
            Ok(f) => f,
            // A recoverable syntax error (e.g. a malformed quantifier): z3 prints
            // the `(error …)` and resyncs to the next command-opening `(`.
            Err(e) if e.recover => {
                out.push(e.msg);
                while p < toks.len() && toks[p] != "(" {
                    p += 1;
                }
                continue;
            }
            Err(e) => return Err(e.msg),
        };
        // Unknown `(set-logic X)`: z3 prints `unsupported` and an ignoring-comment
        // (with the command's position) and proceeds as if no logic were set.
        if let SExpr::List(l) = &form
            && l.len() == 2
            && matches!(&l[0], SExpr::Atom(a) if a == "set-logic")
            && let SExpr::Atom(name) = &l[1]
            && !supported_logic(name)
        {
            let (line, col) = positions[cmd_start];
            out.push("unsupported".to_string());
            out.push(alloc::format!(
                "; ignoring unsupported logic {name} line: {line} position: {col}"
            ));
            continue;
        }
        // `(simplify (root-obj …))`: z3's SMT2 parser handles `root-obj` as a
        // special constructor, evaluating the algebraic root and reporting
        // parse/validation errors at the scanner's exact source column. Handle it
        // straight from the token stream so the columns match z3 byte-for-byte.
        if is_simplify_root_obj(&toks[cmd_start..p]) {
            let pp_decimal = ctx.params.get_bool("pp.decimal", false);
            let prec = ctx.params.get_uint("pp.decimal-precision", 10) as u32;
            out.push(eval_simplify_root_obj(
                &toks[cmd_start..p],
                &positions[cmd_start..p],
                pp_decimal,
                prec,
            ));
            continue;
        }
        out.extend(unknown_attribute_warnings(&form));
        match ctx.command(&form) {
            Ok(Some(resp)) => out.push(resp),
            // A state-changing command that produced no output prints `success`
            // when `:print-success` is on (SMT-LIB compliance mode).
            Ok(None) => {
                if ctx.print_success {
                    out.push("success".to_string());
                }
            }
            Err(msg) => match z3_command_error(&msg, &toks[cmd_start..p], &positions[cmd_start..p])
            {
                // A recoverable error z3 reports as `(error …)` and continues past.
                Some(err) => out.push(err),
                None => return Err(msg),
            },
        }
        if ctx.exited {
            break;
        }
    }
    Ok(())
}

/// Whether `s` is a logic z3 recognises (port of `smt_logics::supported_logic`,
/// substring-based). An unrecognised logic is reported as `unsupported`.
fn supported_logic(s: &str) -> bool {
    let is_all = s == "ALL" || s == "HO_ALL";
    let has_horn = s == "HORN";
    let has_str = s == "QF_S" || s == "QF_SLIA" || s == "QF_SNIA" || is_all;
    let has_arith = ["LRA", "LIRA", "LIA", "NRA", "NIRA", "NIA", "IDL", "RDL"]
        .iter()
        .any(|p| s.contains(p))
        || s == "QF_BVRE"
        || s.contains("FP")
        || s == "QF_S"
        || is_all
        || s == "QF_FD"
        || s == "HORN";
    let has_bv =
        s.contains("BV") || s == "FP" || is_all || s == "QF_FD" || s == "SMTFD" || s == "HORN";
    let has_uf = s.contains("UF") || s == "SMTFD";
    let has_array = s.starts_with("QF_A") || s.starts_with('A') || s == "SMTFD" || s == "HORN";
    let has_seq = s == "QF_BVRE" || has_str;
    let has_fpa = s.contains("FP") || is_all;
    let has_datatype = s.contains("DT") || s == "QF_FD" || is_all || has_horn;
    let has_finite_sets = s.contains("FS") || is_all;
    let has_fd = s == "QF_FD";
    has_uf
        || is_all
        || has_fd
        || has_arith
        || has_bv
        || has_array
        || has_seq
        || has_str
        || has_horn
        || has_fpa
        || has_datatype
        || has_finite_sets
}

/// Whether a command's tokens form `(simplify (root-obj …))` with `root-obj` as
/// the direct argument — the shape z3's SMT2 parser dispatches to `parse_root_obj`.
fn is_simplify_root_obj(ct: &[String]) -> bool {
    ct.len() >= 4 && ct[0] == "(" && ct[1] == "simplify" && ct[2] == "(" && ct[3] == "root-obj"
}

/// The token index of the `)` matching the `(` at `open` (balanced input).
fn matching_close(ct: &[String], open: usize) -> usize {
    let mut depth = 0i32;
    for (i, t) in ct.iter().enumerate().skip(open) {
        match t.as_str() {
            "(" => depth += 1,
            ")" => {
                depth -= 1;
                if depth == 0 {
                    return i;
                }
            }
            _ => {}
        }
    }
    ct.len().saturating_sub(1)
}

/// The number of top-level s-expression children in `ct[start..close]`.
fn count_children(ct: &[String], start: usize, close: usize) -> usize {
    let mut i = start;
    let mut n = 0;
    while i < close {
        if ct[i] == "(" {
            i = matching_close(ct, i) + 1;
        } else {
            i += 1;
        }
        n += 1;
    }
    n
}

/// The result of classifying a `root-obj` index token (a syntactic integer, per
/// z3's `check_int` on the scanner token, then range-checked as z3 does).
enum RootIndex {
    Valid(usize),
    /// Not a syntactic integer token (float, symbol, `(`, `#…`, `+1`, …).
    NotInt,
    /// A negative value, or one exceeding an unsigned machine integer (u32).
    TooBig,
    /// The value 0 (indices are 1-based).
    TooSmall,
}

/// Classify a `root-obj` index token exactly as z3's parser does: `check_int`
/// requires a signed-integer scanner token (`-?[0-9]+`), then the value must be a
/// nonzero unsigned machine integer.
fn classify_root_obj_index(t: &str) -> RootIndex {
    let (neg, digits) = match t.strip_prefix('-') {
        Some(d) => (true, d),
        None => (false, t),
    };
    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return RootIndex::NotInt;
    }
    let is_zero = digits.bytes().all(|b| b == b'0');
    if neg {
        return if is_zero {
            RootIndex::TooSmall
        } else {
            RootIndex::TooBig
        };
    }
    if is_zero {
        return RootIndex::TooSmall;
    }
    match digits.parse::<u64>() {
        Ok(v) if v <= u32::MAX as u64 => RootIndex::Valid(v as usize),
        _ => RootIndex::TooBig,
    }
}

/// `base^k` for a univariate polynomial (repeated multiplication; `k = 0` → 1).
fn poly_pow(base: &Poly<Rational>, k: u32) -> Poly<Rational> {
    let mut acc = Poly::constant(Rational::from_integer(Int::from(1)));
    for _ in 0..k {
        acc = acc.mul(base);
    }
    acc
}

/// Port of z3's `sexpr2upolynomial`: build the univariate polynomial over ℚ from
/// the token stream, consuming exactly one s-expression starting at `*i`. On error
/// returns `(token-index, message)` positioned exactly where z3's scanner sits:
/// the offending atom's token, or a composite's closing `)`.
fn parse_root_obj_poly(
    ct: &[String],
    i: &mut usize,
) -> Result<Poly<Rational>, (usize, &'static str)> {
    let t = ct[*i].as_str();
    if t == "(" {
        let open = *i;
        let close = matching_close(ct, open);
        let head = ct[open + 1].as_str();
        // The first child must be a symbol (not a composite, and not empty `()`).
        if head == "(" || head == ")" {
            return Err((close, "invalid univariate polynomial, symbol expected"));
        }
        let nargs = count_children(ct, open + 2, close);
        match head {
            "+" | "-" | "*" => {
                if nargs == 0 {
                    let m = match head {
                        "+" => {
                            "invalid univariate polynomial, '+' operator expects at least one argument"
                        }
                        "-" => {
                            "invalid univariate polynomial, '-' operator expects at least one argument"
                        }
                        _ => {
                            "invalid univariate polynomial, '*' operator expects at least one argument"
                        }
                    };
                    return Err((close, m));
                }
                *i = open + 2; // first argument
                let mut acc = parse_root_obj_poly(ct, i)?;
                if head == "-" && nargs == 1 {
                    acc = acc.neg();
                }
                for _ in 1..nargs {
                    let arg = parse_root_obj_poly(ct, i)?;
                    acc = match head {
                        "+" => acc.add(&arg),
                        "-" => acc.sub(&arg),
                        _ => acc.mul(&arg),
                    };
                }
                *i = close + 1; // past the closing `)`
                Ok(acc)
            }
            "^" => {
                if nargs != 2 {
                    return Err((
                        close,
                        "invalid univariate polynomial, '^' operator expects two arguments",
                    ));
                }
                *i = open + 2; // base
                let base = parse_root_obj_poly(ct, i)?;
                let etok = *i;
                // The exponent must be a numeral whose value is an unsigned machine
                // integer; a composite exponent is reported at its closing `)`.
                let exp = if ct[etok] == "(" {
                    return Err((
                        matching_close(ct, etok),
                        "invalid univariate polynomial, exponent must be an unsigned integer",
                    ));
                } else {
                    match root_obj_exponent(ct[etok].as_str()) {
                        Some(k) => k,
                        None => {
                            return Err((
                                etok,
                                "invalid univariate polynomial, exponent must be an unsigned integer",
                            ));
                        }
                    }
                };
                *i = close + 1;
                Ok(poly_pow(&base, exp))
            }
            _ => Err((
                close,
                "invalid univariate polynomial, '+', '-', '^' or '*' expected",
            )),
        }
    } else if t.starts_with('#') {
        // A bit-vector / other non-symbol, non-numeral atom (z3's fallthrough).
        let tok = *i;
        *i += 1;
        Err((tok, "invalid univariate polynomial, unexpected "))
    } else if let Some((r, _)) = parse_numeral(t) {
        let tok = *i;
        *i += 1;
        if r.to_integer().is_some() {
            Ok(Poly::constant(r))
        } else {
            Err((
                tok,
                "invalid univariate polynomial, integer coefficient expected",
            ))
        }
    } else {
        // A symbol: only the polynomial variable `x` is allowed.
        let tok = *i;
        *i += 1;
        if t == "x" {
            Ok(Poly::monomial(Rational::from_integer(Int::from(1)), 1))
        } else {
            Err((tok, "invalid univariate polynomial, variable 'x' expected"))
        }
    }
}

/// Parse a `root-obj` univariate polynomial (over the local variable `x`) from an
/// already-parsed s-expression — the term-path counterpart of
/// [`parse_root_obj_poly`], which works on the raw token stream. Accepts `x`,
/// integer numerals, and `+ - * ^` applications; rejects any other symbol
/// (crucially, no declaration of `x` is required and none leaks).
fn sexpr_root_obj_poly(s: &SExpr) -> Result<Poly<Rational>, String> {
    match s {
        SExpr::Atom(a) => {
            if a == "x" {
                Ok(Poly::monomial(Rational::from_integer(Int::from(1)), 1))
            } else if let Some((r, _)) = parse_numeral(a) {
                if r.to_integer().is_some() {
                    Ok(Poly::constant(r))
                } else {
                    Err("invalid univariate polynomial, integer coefficient expected".to_string())
                }
            } else {
                Err("invalid univariate polynomial, variable 'x' expected".to_string())
            }
        }
        SExpr::List(l) if !l.is_empty() => {
            let head = match &l[0] {
                SExpr::Atom(h) => h.as_str(),
                _ => return Err("invalid univariate polynomial, symbol expected".to_string()),
            };
            let nargs = l.len() - 1;
            match head {
                "+" | "-" | "*" => {
                    if nargs == 0 {
                        return Err(alloc::format!(
                            "invalid univariate polynomial, '{head}' operator expects at least one argument"
                        ));
                    }
                    let mut acc = sexpr_root_obj_poly(&l[1])?;
                    if head == "-" && nargs == 1 {
                        acc = acc.neg();
                    }
                    for a in &l[2..] {
                        let arg = sexpr_root_obj_poly(a)?;
                        acc = match head {
                            "+" => acc.add(&arg),
                            "-" => acc.sub(&arg),
                            _ => acc.mul(&arg),
                        };
                    }
                    Ok(acc)
                }
                "^" => {
                    if nargs != 2 {
                        return Err(
                            "invalid univariate polynomial, '^' operator expects two arguments"
                                .to_string(),
                        );
                    }
                    let base = sexpr_root_obj_poly(&l[1])?;
                    let exp = match &l[2] {
                        SExpr::Atom(e) => root_obj_exponent(e).ok_or_else(|| {
                            "invalid univariate polynomial, exponent must be an unsigned integer"
                                .to_string()
                        })?,
                        _ => {
                            return Err(
                                "invalid univariate polynomial, exponent must be an unsigned integer"
                                    .to_string(),
                            );
                        }
                    };
                    Ok(poly_pow(&base, exp))
                }
                _ => {
                    Err("invalid univariate polynomial, '+', '-', '^' or '*' expected".to_string())
                }
            }
        }
        _ => Err("invalid univariate polynomial".to_string()),
    }
}

/// The exponent of a `(^ x k)` term: a numeral whose value is a non-negative
/// machine integer (z3 accepts e.g. `2.0`; rejects `2.5` and negatives).
fn root_obj_exponent(t: &str) -> Option<u32> {
    let (r, _) = parse_numeral(t)?;
    let i = r.to_integer()?;
    let v = i.to_i64()?;
    if (0..=u32::MAX as i64).contains(&v) {
        Some(v as u32)
    } else {
        None
    }
}

/// Parse, validate and evaluate `(simplify (root-obj <poly> <index>))` directly
/// from the command's tokens (`ct`) and their source positions (`cpos`), so every
/// error column matches z3's scanner exactly. Returns the response line: a value,
/// or a positioned `(error …)`.
fn eval_simplify_root_obj(
    ct: &[String],
    cpos: &[(u32, u32)],
    pp_decimal: bool,
    precision: u32,
) -> String {
    let ro_open = 2usize; // `(` of the root-obj application
    let ro_close = matching_close(ct, ro_open);
    let err = |tok: usize, msg: &str| -> String {
        let (l, c) = cpos.get(tok).copied().unwrap_or((0, 0));
        alloc::format!("(error \"line {l} column {c}: {msg}\")")
    };
    // The polynomial is the first argument, at token index 4.
    let mut i = 4usize;
    let poly = match parse_root_obj_poly(ct, &mut i) {
        Ok(p) => p,
        Err((tok, m)) => return err(tok, m),
    };
    // The index token immediately follows the polynomial.
    let idx_tok = i;
    let index = match classify_root_obj_index(ct.get(idx_tok).map_or(")", |s| s.as_str())) {
        RootIndex::Valid(u) => u,
        RootIndex::NotInt => {
            return err(idx_tok, "invalid root-obj, (unsigned) integer expected");
        }
        RootIndex::TooBig => {
            return err(
                idx_tok,
                "invalid root-obj, index must fit in an unsigned machine integer",
            );
        }
        RootIndex::TooSmall => return err(idx_tok, "invalid root-obj, index must be >= 1"),
    };
    // After the index z3 expects the root-obj's closing `)`.
    let after = idx_tok + 1;
    if ct.get(after).map(String::as_str) != Some(")") {
        let got = ct.get(after).map_or("", |s| s.as_str());
        return err(
            after,
            &alloc::format!("invalid root-obj, ')' expected got {got}"),
        );
    }
    // Evaluate. The zero-poly / insufficient-roots errors surface after the
    // root-obj `)` is consumed, so z3 reports them at the following token (here the
    // enclosing `simplify` closing paren).
    match super::algebraic_pp::root_obj_value(&poly, index, pp_decimal, precision) {
        Ok(s) => s,
        Err(super::algebraic_pp::RootObjErr::Zero) => err(
            ro_close + 1,
            "invalid root object, polynomial must not be the zero polynomial",
        ),
        Err(super::algebraic_pp::RootObjErr::Insufficient) => err(
            ro_close + 1,
            "invalid root object, polynomial does have sufficient roots",
        ),
    }
}

/// Translate a recoverable command error into z3's `(error "line L column C: …")`
/// form, locating the offending symbol among the command's tokens. `None` for an
/// error z3rs does not (yet) render z3-compatibly — the caller then aborts.
fn z3_command_error(msg: &str, toks: &[String], positions: &[(u32, u32)]) -> Option<String> {
    // `unknown symbol "X"` → `unknown constant X` at X's first occurrence.
    if let Some(rest) = msg.strip_prefix("unknown symbol \"")
        && let Some(name) = rest.strip_suffix('"')
    {
        let (l, c) = toks
            .iter()
            .position(|t| t == name)
            .map(|i| positions[i])
            .unwrap_or((0, 0));
        return Some(alloc::format!(
            "(error \"line {l} column {c}: unknown constant {name}\")"
        ));
    }
    // `unknown sort 'X'` → same message, positioned at X's first occurrence.
    if let Some(rest) = msg.strip_prefix("unknown sort '")
        && let Some(name) = rest.strip_suffix('\'')
    {
        let (l, c) = toks
            .iter()
            .position(|t| t == name)
            .map(|i| positions[i])
            .unwrap_or((0, 0));
        return Some(alloc::format!(
            "(error \"line {l} column {c}: unknown sort '{name}'\")"
        ));
    }
    // A model/proof/core query without one: reported at the command's closing
    // paren, and the script continues.
    let unavailable = match msg {
        "get-model requires a preceding satisfiable check-sat"
        | "get-value requires a preceding satisfiable check-sat"
        | "eval requires a preceding satisfiable check-sat" => Some("model is not available"),
        "get-proof requires a preceding unsatisfiable check-sat" => Some("proof is not available"),
        "get-unsat-core requires a preceding unsatisfiable check-sat" => {
            Some("unsat core is not available")
        }
        m if m.contains("construction is not enabled") => Some(m),
        _ => None,
    };
    if let Some(what) = unavailable {
        let (l, c) = positions.last().copied().unwrap_or((0, 0));
        return Some(alloc::format!("(error \"line {l} column {c}: {what}\")"));
    }
    // An ill-sorted `((as const S) v)`: reported at the application's closing
    // paren; `#k` says which `(as const` of the command (in token order).
    if let Some(ord) = msg
        .strip_prefix(
            "invalid const array definition, sort mismatch between array range and argument#",
        )
        .and_then(|k| k.parse::<usize>().ok())
    {
        let start = (1..toks.len().saturating_sub(1))
            .filter(|&i| toks[i] == "as" && toks[i + 1] == "const")
            .nth(ord)?
            .checked_sub(2)?;
        let mut depth = 0i32;
        let close = (start..toks.len()).find(|&i| {
            match toks[i].as_str() {
                "(" => depth += 1,
                ")" => depth -= 1,
                _ => {}
            }
            depth == 0
        })?;
        let (l, c) = positions[close];
        return Some(alloc::format!(
            "(error \"line {l} column {c}: invalid const array definition, sort mismatch between array range and argument\")"
        ));
    }
    // Ill-sorted recursive definition. z3 reports it once the whole command is
    // parsed: for `define-fun-rec` at the command's closing paren (the last
    // token), for `define-funs-rec` at the bodies-list closing paren (the
    // second-to-last token, before the command close).
    if msg.starts_with("invalid function definition, sort mismatch.") {
        let idx = match toks.get(1).map(String::as_str) {
            Some("define-funs-rec") if positions.len() >= 2 => positions.len() - 2,
            _ => positions.len().saturating_sub(1),
        };
        let (l, c) = positions.get(idx).copied().unwrap_or((0, 0));
        return Some(alloc::format!("(error \"line {l} column {c}: {msg}\")"));
    }
    None
}

/// A persistent SMT-LIB2 session. Unlike [`run`], declarations, assertions, the
/// push/pop stack, and options carry across [`Session::eval`] calls, so a caller
/// can drive the solver incrementally (the C API's solver object builds on it).
pub struct Session {
    ctx: Context,
}

impl Default for Session {
    fn default() -> Session {
        Session::new()
    }
}

impl Session {
    /// A fresh session with no declarations or assertions.
    pub fn new() -> Session {
        Session {
            ctx: Context::new(),
        }
    }

    /// Interpret more SMT-LIB2 `script` against the accumulated state, returning
    /// one response line per command that produces output (e.g. `check-sat`,
    /// `get-value`).
    pub fn eval(&mut self, script: &str) -> Result<Vec<String>, String> {
        let forms = parse(script)?;
        let mut out = Vec::new();
        for form in forms {
            if let Some(resp) = self.ctx.command(&form)? {
                out.push(resp);
            }
            if self.ctx.exited {
                break;
            }
        }
        Ok(out)
    }
}

/// Interpret an SMT-LIB 1.2 `(benchmark name :attr value …)`: declare its
/// sorts/functions/predicates, assert the assumptions and formula, and return
/// the single `check-sat` verdict. Quantifiers are out of scope.
fn run_v1(l: &[SExpr]) -> Result<Vec<String>, String> {
    let mut ctx = Context::new();
    let mut asserts: Vec<SExpr> = Vec::new();
    // l[0] = "benchmark", l[1] = name, then :keyword value pairs.
    let mut i = 2;
    while i < l.len() {
        let key = Context::sym(&l[i])?.to_string();
        let val = l
            .get(i + 1)
            .ok_or_else(|| alloc::format!("benchmark: {key} has no value"))?;
        match key.as_str() {
            ":extrasorts" => {
                for s in as_list(val)? {
                    let name = Context::sym(s)?.to_string();
                    let sort = ctx.m.mk_uninterpreted_sort(Symbol::new(&name));
                    ctx.sorts.insert(name, sort);
                }
            }
            ":extrafuns" => {
                for f in as_list(val)? {
                    // (name dom… range)
                    let parts = as_list(f)?;
                    let name = Context::sym(&parts[0])?.to_string();
                    let range = ctx.resolve_sort(&parts[parts.len() - 1])?;
                    let domain: Vec<AstId> = parts[1..parts.len() - 1]
                        .iter()
                        .map(|s| ctx.resolve_sort(s))
                        .collect::<Result<_, _>>()?;
                    let d = ctx.m.mk_func_decl(Symbol::new(&name), &domain, range);
                    ctx.funcs.insert(name, d);
                }
            }
            ":extrapreds" => {
                for p in as_list(val)? {
                    // (name dom…) — range Bool
                    let parts = as_list(p)?;
                    let name = Context::sym(&parts[0])?.to_string();
                    let bool_s = ctx.m.mk_bool_sort();
                    let domain: Vec<AstId> = parts[1..]
                        .iter()
                        .map(|s| ctx.resolve_sort(s))
                        .collect::<Result<_, _>>()?;
                    let d = ctx.m.mk_func_decl(Symbol::new(&name), &domain, bool_s);
                    ctx.funcs.insert(name, d);
                }
            }
            ":assumption" | ":formula" => asserts.push(v1_to_v2(val)),
            // :logic, :status, :notes, :source, :difficulty, :category, … ignored.
            _ => {}
        }
        i += 2;
    }
    for a in &asserts {
        let t = ctx.term(a)?;
        ctx.assertions.push(t);
    }
    let goal = ctx.goal();
    let (res, _) = ctx.decide(goal);
    Ok(alloc::vec![verdict_word(res).to_string()])
}

/// The integer value following the keyword `key` in a command's tail, if any
/// (e.g. `:weight 5`).
fn attr_int(list: &[SExpr], key: &str) -> Option<i64> {
    let pos = list
        .iter()
        .position(|s| matches!(s, SExpr::Atom(a) if a == key))?;
    match list.get(pos + 1) {
        Some(SExpr::Atom(a)) => a.parse().ok(),
        _ => None,
    }
}

/// If `s` is a top-level `(forall …)` or `(exists …)`, its keyword.
/// Peel nested `forall` binders (and transparent `!` annotations) from a
/// quantifier body, returning the extra binders and the innermost body. So
/// `∀y.∀z. φ` contributes `[y, z]` and `φ`.
/// Substitute atom names by S-expressions throughout `e` (no capture avoidance —
/// used for Skolemization, where the replacements are fresh applications).
fn subst_sexpr(e: &SExpr, subst: &[(String, SExpr)]) -> SExpr {
    match e {
        SExpr::Atom(a) => {
            for (n, r) in subst {
                if n == a {
                    return r.clone();
                }
            }
            e.clone()
        }
        SExpr::List(l) => SExpr::List(l.iter().map(|x| subst_sexpr(x, subst)).collect()),
    }
}

fn flatten_foralls(body: &SExpr) -> (Vec<SExpr>, SExpr) {
    let mut extra: Vec<SExpr> = Vec::new();
    let mut cur = body.clone();
    loop {
        let step = match &cur {
            SExpr::List(l) if l.len() >= 2 && matches!(&l[0], SExpr::Atom(a) if a == "!") => {
                Some(l[1].clone())
            }
            SExpr::List(l) if l.len() == 3 && matches!(&l[0], SExpr::Atom(a) if a == "forall") => {
                if let SExpr::List(bs) = &l[1] {
                    extra.extend(bs.iter().cloned());
                    Some(l[2].clone())
                } else {
                    None
                }
            }
            _ => None,
        };
        match step {
            Some(n) => cur = n,
            None => break,
        }
    }
    (extra, cur)
}

/// Rename every free occurrence of the atom `from` in `e` to `to` (inner
/// binders of the same name shadow it).
fn rename_free(e: &SExpr, from: &str, to: &str) -> SExpr {
    match e {
        SExpr::Atom(a) if a == from => SExpr::Atom(to.to_string()),
        SExpr::Atom(_) => e.clone(),
        SExpr::List(l) => {
            let binds = |b: &SExpr| match b {
                SExpr::List(bs) => bs.iter().any(|p| match p {
                    SExpr::List(pv) => matches!(pv.first(), Some(SExpr::Atom(n)) if n == from),
                    _ => false,
                }),
                _ => false,
            };
            if l.len() == 3
                && matches!(&l[0], SExpr::Atom(h) if h == "forall" || h == "exists" || h == "let")
                && binds(&l[1])
            {
                return e.clone();
            }
            SExpr::List(l.iter().map(|x| rename_free(x, from, to)).collect())
        }
    }
}

/// Pull non-arithmetic universals out of a quantifier body where that is
/// equivalent: a
/// `forall` in positive position (under `and`/`or`, the consequent of `=>`,
/// an `ite` branch, double negation) or an `exists` in negative position,
/// its binders renamed fresh and appended to `extra`. `∀x. ite(c, ∀y. φ, ψ)`
/// is `∀x y. ite(c, φ, ψ)`, which instantiation handles instead of an opaque
/// nested quantifier.
fn prenex_positive(e: &SExpr, pos: bool, extra: &mut Vec<SExpr>, counter: &mut u32) -> SExpr {
    prenex_positive_with(e, pos, extra, counter, false)
}

/// [`prenex_positive`], also pulling out arithmetic binders when `arith`
/// (for quantifiers that quantifier elimination could not remove).
fn prenex_positive_with(
    e: &SExpr,
    pos: bool,
    extra: &mut Vec<SExpr>,
    counter: &mut u32,
    arith: bool,
) -> SExpr {
    let SExpr::List(l) = e else { return e.clone() };
    let Some(SExpr::Atom(h)) = l.first() else {
        return e.clone();
    };
    match h.as_str() {
        "and" | "or" => SExpr::List(
            core::iter::once(l[0].clone())
                .chain(
                    l[1..]
                        .iter()
                        .map(|x| prenex_positive_with(x, pos, extra, counter, arith)),
                )
                .collect(),
        ),
        "not" if l.len() == 2 => SExpr::List(alloc::vec![
            l[0].clone(),
            prenex_positive_with(&l[1], !pos, extra, counter, arith)
        ]),
        "=>" if l.len() == 3 => SExpr::List(alloc::vec![
            l[0].clone(),
            prenex_positive_with(&l[1], !pos, extra, counter, arith),
            prenex_positive_with(&l[2], pos, extra, counter, arith),
        ]),
        "ite" if l.len() == 4 => SExpr::List(alloc::vec![
            l[0].clone(),
            l[1].clone(),
            prenex_positive_with(&l[2], pos, extra, counter, arith),
            prenex_positive_with(&l[3], pos, extra, counter, arith),
        ]),
        "forall" | "exists" if l.len() == 3 && (h == "forall") == pos => {
            let SExpr::List(bs) = &l[1] else {
                return e.clone();
            };
            // Arithmetic binders stay nested: quantifier elimination decides
            // those exactly (inner block first).
            let is_arith = |b: &SExpr| matches!(b, SExpr::List(pv) if matches!(pv.get(1), Some(SExpr::Atom(s)) if s == "Int" || s == "Real"));
            if !arith && bs.iter().any(is_arith) {
                return e.clone();
            }
            let mut body = l[2].clone();
            for b in bs {
                let SExpr::List(pv) = b else { return e.clone() };
                let (Some(SExpr::Atom(n)), Some(sort)) = (pv.first(), pv.get(1)) else {
                    return e.clone();
                };
                let fresh = alloc::format!("!pnx{}", *counter);
                *counter += 1;
                body = rename_free(&body, n, &fresh);
                extra.push(SExpr::List(alloc::vec![SExpr::Atom(fresh), sort.clone()]));
            }
            prenex_positive_with(&body, pos, extra, counter, arith)
        }
        _ => e.clone(),
    }
}

/// Does `e` contain a body-less `(let (bindings))`?
fn has_bodyless_let(e: &SExpr) -> bool {
    match e {
        SExpr::Atom(_) => false,
        SExpr::List(l) => {
            (l.len() == 2 && matches!(&l[0], SExpr::Atom(h) if h == "let"))
                || l.iter().any(has_bodyless_let)
        }
    }
}

/// Replace every body-less `(let ((x₁ t₁) … (xₙ tₙ)))` by `tₙ`, as z3's
/// stack-based parser does: when the `let` frame closes without a body, the
/// expression on top of its stack — the last binding's value, parsed in the
/// outer scope — becomes the result (`smt2parser::pop_let_frame`).
fn fill_bodyless_let(e: &SExpr) -> SExpr {
    let SExpr::List(l) = e else { return e.clone() };
    if l.len() == 2
        && matches!(&l[0], SExpr::Atom(h) if h == "let")
        && let SExpr::List(bs) = &l[1]
        && let Some(SExpr::List(last)) = bs.last()
        && last.len() == 2
    {
        return fill_bodyless_let(&last[1]);
    }
    SExpr::List(l.iter().map(fill_bodyless_let).collect())
}

/// Push a leading `not` through a top-level quantifier so negated quantifiers
/// get sound handling instead of falling back to `unknown`:
/// `¬∃x.φ ⇒ ∀x.¬φ`, `¬∀x.φ ⇒ ∃x.¬φ`, and `¬¬φ ⇒ φ`. Applied repeatedly.
fn push_not_quantifier(s: &SExpr) -> SExpr {
    if let SExpr::List(l) = s
        && l.len() == 2
        && matches!(&l[0], SExpr::Atom(a) if a == "not")
    {
        if let SExpr::List(inner) = &l[1]
            && inner.len() == 3
            && let SExpr::Atom(h) = &inner[0]
            && let Some(q) = match h.as_str() {
                "forall" => Some("exists"),
                "exists" => Some("forall"),
                _ => None,
            }
        {
            let negbody = SExpr::List(alloc::vec![
                SExpr::Atom("not".to_string()),
                inner[2].clone()
            ]);
            let rewritten = SExpr::List(alloc::vec![
                SExpr::Atom(q.to_string()),
                inner[1].clone(),
                negbody
            ]);
            return push_not_quantifier(&rewritten);
        }
        // `¬¬φ ⇒ φ`, so a doubly-negated quantifier is still reached.
        if let SExpr::List(inner) = &l[1]
            && inner.len() == 2
            && matches!(&inner[0], SExpr::Atom(a) if a == "not")
        {
            return push_not_quantifier(&inner[1]);
        }
    }
    s.clone()
}

fn top_level_quantifier(s: &SExpr) -> Option<&'static str> {
    if let SExpr::List(l) = s
        && l.len() == 3
        && let SExpr::Atom(h) = &l[0]
    {
        return match h.as_str() {
            "forall" => Some("forall"),
            "exists" => Some("exists"),
            _ => None,
        };
    }
    None
}

/// The elements of a list s-expression.
fn as_list(s: &SExpr) -> Result<&[SExpr], String> {
    match s {
        SExpr::List(l) => Ok(l),
        SExpr::Atom(_) => Err("expected a list".to_string()),
    }
}

/// Rewrite an SMT-LIB 1.2 formula into the equivalent SMT-LIB 2 s-expression:
/// `implies`→`=>`, `if_then_else`→`ite`, `iff`→`=`, and the single-binding
/// `(let (v t) b)` / `(flet (v f) b)` into `(let ((v t)) b)`.
fn v1_to_v2(s: &SExpr) -> SExpr {
    let SExpr::List(l) = s else {
        return s.clone();
    };
    let head = match l.first() {
        Some(SExpr::Atom(a)) => a.as_str(),
        _ => return SExpr::List(l.iter().map(v1_to_v2).collect()),
    };
    let atom = |s: &str| SExpr::Atom(String::from(s));
    match head {
        "implies" if l.len() == 3 => {
            SExpr::List(alloc::vec![atom("=>"), v1_to_v2(&l[1]), v1_to_v2(&l[2])])
        }
        "if_then_else" if l.len() == 4 => SExpr::List(alloc::vec![
            atom("ite"),
            v1_to_v2(&l[1]),
            v1_to_v2(&l[2]),
            v1_to_v2(&l[3]),
        ]),
        "iff" if l.len() == 3 => {
            SExpr::List(alloc::vec![atom("="), v1_to_v2(&l[1]), v1_to_v2(&l[2])])
        }
        "let" | "flet" if l.len() == 3 => {
            // (let (v t) body) → (let ((v t)) body)
            if let SExpr::List(bind) = &l[1]
                && bind.len() == 2
            {
                let inner = SExpr::List(alloc::vec![bind[0].clone(), v1_to_v2(&bind[1])]);
                let binds = SExpr::List(alloc::vec![inner]);
                return SExpr::List(alloc::vec![atom("let"), binds, v1_to_v2(&l[2])]);
            }
            SExpr::List(l.iter().map(v1_to_v2).collect())
        }
        _ => SExpr::List(l.iter().map(v1_to_v2).collect()),
    }
}

// --- tokenizer + parser ---------------------------------------------------

/// Tokenize, recording each token's source position as `(line, column)` with
/// 1-based line and 0-based column (matching z3's diagnostics).
fn tokenize(input: &str) -> (Vec<String>, Vec<(u32, u32)>) {
    let chars: Vec<char> = input.chars().collect();
    let mut i = 0usize;
    let mut line: u32 = 1;
    let mut col: u32 = 0;
    let mut toks: Vec<String> = Vec::new();
    let mut positions: Vec<(u32, u32)> = Vec::new();
    // Consume `chars[i]`, advancing the line/column counters.
    macro_rules! adv {
        () => {{
            if chars[i] == '\n' {
                line += 1;
                col = 0;
            } else {
                col += 1;
            }
            i += 1;
        }};
    }
    while i < chars.len() {
        let c = chars[i];
        let start = (line, col);
        match c {
            ';' => {
                // comment to end of line
                while i < chars.len() && chars[i] != '\n' {
                    adv!();
                }
            }
            c if c.is_whitespace() => {
                adv!();
            }
            '(' | ')' => {
                toks.push(c.to_string());
                positions.push(start);
                adv!();
            }
            '{' => {
                // SMT-LIB v1 annotation block `{ … }` (e.g. :source); depth-matched
                // and kept as one opaque token.
                adv!();
                let mut s = String::from("{");
                let mut depth = 1;
                while i < chars.len() {
                    let c = chars[i];
                    adv!();
                    if c == '{' {
                        depth += 1;
                    } else if c == '}' {
                        depth -= 1;
                        if depth == 0 {
                            break;
                        }
                    }
                    s.push(c);
                }
                s.push('}');
                toks.push(s);
                positions.push(start);
            }
            '"' => {
                // String literal "…"; a doubled "" is an embedded quote. Kept
                // with its surrounding quotes so it stays a single, recognizable
                // token.
                adv!(); // opening quote
                let mut s = String::from("\"");
                while i < chars.len() {
                    let c = chars[i];
                    adv!();
                    if c == '"' {
                        if i < chars.len() && chars[i] == '"' {
                            s.push('"');
                            s.push('"');
                            adv!();
                            continue;
                        }
                        break;
                    }
                    s.push(c);
                }
                s.push('"'); // closing quote
                toks.push(s);
                positions.push(start);
            }
            '|' => {
                // quoted symbol |...|
                adv!();
                let mut s = String::new();
                while i < chars.len() {
                    let c = chars[i];
                    adv!();
                    if c == '|' {
                        break;
                    }
                    s.push(c);
                }
                toks.push(s);
                positions.push(start);
            }
            _ => {
                let mut s = String::new();
                while i < chars.len() {
                    let c = chars[i];
                    if c.is_whitespace() || c == '(' || c == ')' || c == ';' {
                        break;
                    }
                    s.push(c);
                    adv!();
                }
                toks.push(s);
                positions.push(start);
            }
        }
    }
    (toks, positions)
}

fn parse(input: &str) -> Result<Vec<SExpr>, String> {
    let (toks, positions) = tokenize(input);
    let mut pos = 0;
    let mut forms = Vec::new();
    while pos < toks.len() {
        forms.push(parse_one(&toks, &positions, &mut pos).map_err(|e| e.msg)?);
    }
    Ok(forms)
}

/// A parse failure. `recover` distinguishes errors z3 reports and then resyncs
/// past (`(error …)` already formatted in `msg`) from ones that abort the run.
struct ParseErr {
    msg: String,
    recover: bool,
}

/// Render an s-expression back to its textual form (used to echo `get-value`
/// query terms).
fn render_sexpr(s: &SExpr) -> String {
    match s {
        // The tokenizer strips `|…|` from a quoted symbol; restore it. String
        // literals, keywords, `#x`/`#b` numerals and decimals are not symbols.
        SExpr::Atom(a)
            if !a.starts_with(['"', ':', '#'])
                && !a.chars().all(|c| c.is_ascii_digit() || c == '.') =>
        {
            crate::util::symbol::smt2_symbol(a).into_owned()
        }
        SExpr::Atom(a) => a.clone(),
        SExpr::List(l) => {
            let inner: Vec<String> = l.iter().map(render_sexpr).collect();
            alloc::format!("({})", inner.join(" "))
        }
    }
}

/// Whether any atom anywhere in `s` contains the substring `needle` (used to
/// spot a tactic name like `nlsat` inside a `check-sat-using` tactic term).
fn sexpr_mentions(s: &SExpr, needle: &str) -> bool {
    match s {
        SExpr::Atom(a) => a.contains(needle),
        SExpr::List(l) => l.iter().any(|e| sexpr_mentions(e, needle)),
    }
}

fn parse_one(
    toks: &[String],
    positions: &[(u32, u32)],
    pos: &mut usize,
) -> Result<SExpr, ParseErr> {
    let tok = &toks[*pos];
    *pos += 1;
    match tok.as_str() {
        "(" => {
            let mut list = Vec::new();
            loop {
                if *pos >= toks.len() {
                    return Err(ParseErr {
                        msg: "unexpected end of input (missing `)`)".to_string(),
                        recover: false,
                    });
                }
                if toks[*pos] == ")" {
                    *pos += 1;
                    break;
                }
                list.push(parse_one(toks, positions, pos)?);
            }
            // A quantifier binds `((<symbol> <sort>)*) <expr>` — exactly one body.
            // z3 reports a wrong body count at the closing paren and resyncs.
            if let Some(SExpr::Atom(h)) = list.first()
                && (h == "forall" || h == "exists" || h == "lambda")
                && list.len() != 3
            {
                let (l, c) = positions.get(*pos - 1).copied().unwrap_or((0, 0));
                return Err(ParseErr {
                    msg: alloc::format!(
                        "(error \"line {l} column {c}: invalid quantified expression, syntax error: \
                         (forall|exists ((<symbol> <sort>)*) <expr>) expected\")"
                    ),
                    recover: true,
                });
            }
            Ok(SExpr::List(list))
        }
        ")" => Err(ParseErr {
            msg: "unexpected `)`".to_string(),
            recover: false,
        }),
        atom => Ok(SExpr::Atom(atom.to_string())),
    }
}

// --- interpreter ----------------------------------------------------------

/// A saved assertion-stack level (`push` records one; `pop` restores it),
/// capturing the sizes of the assertion and declaration lists so that `pop`
/// discards everything asserted or declared since the matching `push` — SMT-LIB
/// scopes declarations, not just assertions.
struct Scope {
    assertions: usize,
    decls: usize,
    sorts: usize,
    universals: usize,
    quant_defs: usize,
    /// Length of `decl_table_stack` at the push.
    table: usize,
    /// Length of `asserted_mentions` at the push.
    mentions: usize,
}

struct Context {
    m: AstManager,
    sorts: BTreeMap<String, AstId>,
    funcs: BTreeMap<String, AstId>,
    assertions: Vec<AstId>,
    /// The `:named` label of each assertion (parallel to `assertions`), if any —
    /// used to report an unsat core.
    assert_names: Vec<Option<String>>,
    /// `:named` assertion labels as `(name, term, assertion index)`: a name
    /// denotes its term (e.g. as a `check-sat-assuming` literal).
    named_terms: Vec<(String, AstId, usize)>,
    /// The verdict of the most recent `check-sat`.
    last_verdict: Option<SmtResult>,
    /// Set by `(exit)`: subsequent commands in the script are ignored.
    exited: bool,
    /// `:print-success` (also enabled by `:smtlib2-compliant`): when true, every
    /// state-changing command that succeeds prints `success`.
    print_success: bool,
    /// The logic set by `(set-logic …)`, if any. When set, sorts/operators
    /// outside the logic's theories are rejected as z3 does (e.g. `Array` under
    /// `BV`). `None` means no restriction (the permissive `ALL` default).
    logic: Option<String>,
    /// `:rewriter.hi-div0` (z3's default: true) — use the "hardware
    /// interpretation" of bit-vector division by zero (`bvudiv x 0 = 0b1…1`,
    /// `bvurem x 0 = x`). When false, division by zero is an *uninterpreted*
    /// function of the dividend, which is strictly more permissive.
    hi_div0: bool,
    /// Sorts introduced by a nullary `(declare-sort S)`. These are the only sorts
    /// with *no* intended semantics, so only these may be given an arbitrary
    /// finite domain by finite model finding. (A null AST family is **not** a
    /// usable test: `fp_sort`, `string_sort`, … are all built on
    /// `mk_uninterpreted_sort` too, and giving `Float64` a 4-element domain would
    /// happily "prove" `∀a. fp.isNaN a`.)
    declared_sorts: BTreeSet<AstId>,
    /// Saved scope levels (for `pop` to restore).
    scope_stack: Vec<Scope>,
    /// Active `let`/macro-parameter binding scopes (innermost last).
    scopes: Vec<Vec<(String, AstId)>>,
    /// `define-fun` macros: name → (parameter names, body).
    macros: BTreeMap<String, (Vec<String>, SExpr)>,
    /// Declared constants/functions in declaration order (for `get-model` and
    /// declaration scoping).
    decl_order: Vec<String>,
    /// The slot layout of z3's declaration dictionary, which orders the
    /// constants and functions `get-model` lists beyond the solver's own.
    decl_table: DeclTable,
    /// Every name entered into `decl_table`, in order, for scoped removal.
    decl_table_stack: Vec<String>,
    /// The declared function and `define-fun` names each `assert` mentions
    /// (scoped like the assertions), which decide the declarations the
    /// printed model lists first.
    asserted_mentions: Vec<String>,
    /// z3's combined solver switched to its incremental core (a push/pop, an
    /// assertion after a `check-sat`, or assumptions): no `solve-eqs`
    /// preprocessing, so no eliminated variables in the model.
    inc_mode: bool,
    /// A `check-sat` has run (later assertions switch to incremental mode).
    check_sat_done: bool,
    /// Constants a top-level `x = t` assertion defines (`solve-eqs`
    /// candidates), in assertion order.
    solved_vars: Vec<String>,
    /// Declared (uninterpreted) sort names in declaration order, for scoping.
    sort_order: Vec<String>,
    /// The model from the most recent satisfiable `check-sat`, if still current.
    last_model: Option<Model>,
    /// Counter for the fresh constants introduced by term-ITE elimination.
    fresh_counter: u32,
    /// Boolean sentinels standing in for (not-yet-decided) quantified formulas;
    /// a goal that mentions any of these is answered `unknown` (see `decide`).
    quant_atoms: BTreeSet<AstId>,
    /// Predicates abstracting nested quantified formulas over their free
    /// variables (`∀y. q(x, y)` inside `∀x. …` becomes `!qp!k(x)`), one per
    /// alpha-equivalence class keyed by the canonical text. Applications are
    /// sentinels like [`Self::quant_atoms`]: never confirmed by a model.
    quant_preds: BTreeMap<String, (AstId, usize)>,
    /// The declarations in [`Self::quant_preds`].
    quant_pred_decls: BTreeSet<AstId>,
    /// The definitions of the [`Self::quant_preds`] abstractions (see
    /// [`Self::quant_definition`]), as universals (no binder: a ground fact);
    /// added only to look for a refutation once a check is undecided.
    quant_defs: Vec<(Vec<AstId>, AstId)>,
    /// Set while a check runs with [`Self::quant_defs`] added.
    in_quant_defs: bool,
    /// The [`Self::quant_pred_decls`] whose two definitions (instantiable and
    /// skolemized) are both in [`Self::quant_defs`], with the definition count
    /// after them. With those definitions asserted, a model in which every
    /// universal holds gives such a predicate exactly its formula's value, so
    /// it is no sentinel then.
    quant_pred_exact: BTreeMap<AstId, usize>,
    /// User `:pattern` trigger sets of top-level universals, by body.
    universal_patterns: BTreeMap<AstId, Vec<Vec<AstId>>>,
    /// Arrays the last satisfiable check read as functions (array constant →
    /// function), see [`Self::arrays_as_functions`].
    array_fns: BTreeMap<AstId, AstId>,
    /// E-matching equality classes (term → class index) and their members,
    /// rebuilt by [`Self::ematch_rebuild_classes`] during instantiation.
    ematch_class: BTreeMap<AstId, usize>,
    ematch_members: Vec<Vec<AstId>>,
    /// Enumeration datatypes: sort → its constructor constants. Reasoned about
    /// as a finite uninterpreted sort with distinct elements and a domain axiom.
    enums: BTreeMap<AstId, Vec<AstId>>,
    /// Record/tuple datatypes (a single constructor with fields): sort →
    /// `(constructor decl, selector decls)`. Reasoned about with the
    /// selector-over-constructor and constructor-surjectivity (eta) axioms.
    records: BTreeMap<AstId, (AstId, Vec<AstId>)>,
    /// General datatypes with ≥2 constructors that have fields:
    /// sort → per-constructor `(constructor decl, selector decls, tester decl)`.
    datatypes: BTreeMap<AstId, Vec<(AstId, Vec<AstId>, AstId)>>,
    /// For each recursive datatype, an uninterpreted `depth : DT → Int` used to
    /// enforce acyclicity (a constructor is strictly deeper than its recursive
    /// children, so no term can be its own descendant).
    dt_depth: BTreeMap<AstId, AstId>,
    /// Constructor name → its tester declaration (for `((_ is C) t)`).
    tester_of: BTreeMap<String, AstId>,
    /// Parametric (polymorphic) datatype templates: name → (type parameters,
    /// constructor s-expressions). Monomorphized on use, e.g. `(Pair Int Bool)`.
    param_datatypes: BTreeMap<String, (Vec<String>, Vec<SExpr>)>,
    /// Monomorphized parametric-datatype instances: concrete sort → (base name,
    /// argument sorts), so the internal `Tree!12` prints as `(Tree Bool)`.
    mono_datatypes: BTreeMap<AstId, (String, Vec<AstId>)>,
    /// Every declaration registered under a given name, in registration order.
    /// A datatype constructor/selector name may be *overloaded* across
    /// monomorphic instances (`value : (Tree Int) → Int` and `(Tree Bool) →
    /// Bool`); an application resolves to the candidate whose domain matches its
    /// argument sorts, matching z3's overload resolution.
    overloads: BTreeMap<String, Vec<AstId>>,
    /// Array `lambda` closures: array term → (bound-variable placeholders, body).
    /// `(select (lambda ((x S)) body) i)` beta-reduces to `body[x:=i]`.
    lambdas: BTreeMap<AstId, (Vec<AstId>, AstId)>,
    /// Array `(_ map f)` combinators: array term → (function name, source arrays).
    /// `(select ((_ map f) a…) i)` rewrites to `f((select a i)…)`.
    maps: BTreeMap<AstId, (String, Vec<AstId>)>,
    /// `(_ as-array f)` values: array term → the function declaration.
    /// `(select (_ as-array f) i)` rewrites to `f(i)`.
    as_arrays: BTreeMap<AstId, AstId>,
    /// Function references passed to `seq.map`/`seq.mapi`/`seq.foldl`/
    /// `seq.foldli`: placeholder array term → the declared function or macro
    /// name it stands for (applied by name, never read as an array).
    fn_refs: BTreeMap<AstId, String>,
    /// Curried `select` chains built for a multi-argument function argument
    /// of those operations: z3 forms one multi-index `select` there, so they
    /// print as `(select f i j)`.
    multi_selects: BTreeSet<AstId>,
    /// Top-level universal (`forall`) assertions as `(bound-var placeholders,
    /// body)`; instantiated over ground terms at each `check-sat`.
    universals: Vec<(Vec<AstId>, AstId)>,
    /// Optimization objectives (`maximize`/`minimize`/`assert-soft` groups).
    objectives: Vec<Objective>,
    /// The rendered optimal value of each objective after the last `check-sat`.
    objective_values: Vec<String>,
    /// `box`/`pareto` iteration state across repeated `check-sat`s.
    opt_iter: OptIter,
    /// Set by [`Self::optimize_one`] when a nonlinear objective's optimum is
    /// an open limit (no model attains it, so nothing can be committed).
    opt_open_limit: bool,
    /// Why the last `check-sat` answered `unknown`, when more specific than
    /// z3's generic `incomplete`.
    reason_unknown: Option<String>,
    /// The interned `String` sort, once used.
    string_sort: Option<AstId>,
    /// String literal text → its distinct constant of the `String` sort.
    str_lits: BTreeMap<String, AstId>,
    /// The `str.len : String → Int` function declaration, once used.
    str_len_decl: Option<AstId>,
    /// Symbolic (non-constant-folded) string-producing operations. A goal that
    /// mentions any is answered `unknown` (their word semantics aren't solved),
    /// keeping every definite verdict sound.
    str_symbolic: BTreeSet<AstId>,
    /// The concrete `(string var → literal)` assignment from the last successful
    /// string-witness search, so `get-value`/`get-model` report a concrete string
    /// (e.g. `"aaa"`) rather than an uninterpreted placeholder.
    str_witness: Vec<(AstId, AstId)>,
    /// The `v = literal` bindings the last `inline_str_bindings` substituted.
    str_inlined: Vec<(AstId, AstId)>,
    /// Length links for symbolic string predicates: `(pred_app, longer, shorter)`
    /// asserts `pred_app ⇒ str.len(longer) ≥ str.len(shorter)` — sound for
    /// `str.contains`/`str.prefixof`/`str.suffixof`, and enough to refute e.g.
    /// `str.contains x "a" ∧ str.len x = 0`.
    str_pred_len: Vec<(AstId, AstId, AstId)>,
    /// Constant upper bounds on a string marker's length: `(marker, k)` asserts
    /// `str.len(marker) ≤ k` (e.g. `str.at` yields ≤ 1 character).
    str_len_ub: Vec<(AstId, i64)>,
    /// Each symbolic string marker's declaration → the string op it stands for,
    /// so a candidate assignment can *re-fold* it concretely during the bounded
    /// string-witness search (the `sat` direction).
    str_op_decls: BTreeMap<AstId, String>,
    /// Congruence cache for symbolic string/seq op markers: the same `(op, args)`
    /// reuses one marker, so `str.to_int x` reads the same value everywhere.
    str_marker_cache: BTreeMap<(String, alloc::vec::Vec<AstId>), AstId>,
    /// The interned `RegLan` (regular language) sort, once used.
    reglan_sort: Option<AstId>,
    /// Regex terms whose structure is fully constant, for `str.in_re` folding.
    regex_of: BTreeMap<AstId, Regex>,
    /// `(str.to_re t)` regex terms over a non-literal string `t`, mapped to `t`,
    /// so `(str.in_re s (str.to_re t))` lowers to `s = t` as z3's seq rewriter does.
    regex_to_re_arg: BTreeMap<AstId, AstId>,
    /// Parametric sort macros from `define-sort`: name → (params, body).
    sort_defs: BTreeMap<String, (Vec<String>, SExpr)>,
    /// Floating-point sorts `(_ FloatingPoint eb sb)`, keyed by `(eb, sb)`.
    fp_sorts: BTreeMap<(u32, u32), AstId>,
    /// Opaque to_fp conversion markers -> (rm, x, eb, sb, unsigned). `unsigned`
    /// records whether the source was `to_fp_unsigned` (only meaningful when `x`
    /// is a bit-vector, where the sign of the top bit changes the numeric value).
    fp_conv: BTreeMap<AstId, (AstId, AstId, u32, u32, bool)>,
    /// Opaque `fp.rem` markers -> (x, y, eb, sb). Folded once both operands are
    /// pinned to concrete FP constants by top-level equalities.
    fp_rem_markers: BTreeMap<AstId, (AstId, AstId, u32, u32)>,
    /// Unspecified `fp.to_ubv`/`fp.to_sbv` results (NaN/∞/out-of-range constant
    /// input, constant rounding mode), cached by `(signed, m, rm, x)` so identical
    /// applications share one free bit-vector (z3 congruence: the result is an
    /// uninterpreted value distinguished by the full application).
    fp_to_bv_unspec: BTreeMap<(bool, u32, AstId, AstId), AstId>,
    /// Unspecified sign of an `fp.min`/`fp.max` ±0 clash, cached by
    /// `(is_min, a, b)` so identical applications share one free 1-bit sign
    /// (SMT-LIB leaves the result sign of `min(+0,-0)`/`max(+0,-0)` unspecified,
    /// but it is a function: same operands ⇒ same zero). A free 1-bit value is
    /// already exactly `{+0, -0}`, so no extra constraint is needed.
    fp_minmax_zero_sign: BTreeMap<(bool, AstId, AstId), AstId>,
    /// Gated `fp.to_ubv`/`fp.to_sbv` markers over a *symbolic* FP `x` (constant
    /// rounding mode): marker BV → `(signed, m, rm_code, rm, x)`. Re-folded once
    /// `x` is pinned to a concrete FP constant by a top-level equality.
    fp_to_bv_markers: BTreeMap<AstId, (bool, u32, u32, AstId, AstId)>,
    /// Opaque FP classification-predicate markers (`fp.isNaN`/`isNormal`/… whose
    /// operand could not be bit-blasted, e.g. a `to_fp` conversion of a symbolic
    /// real/int) -> (op name, FP operand). Resolved once the operand's value is
    /// pinned to a concrete FP constant (via `fold_fp_conversions`), so the
    /// predicate does not stay a free Boolean (a fuzz-found spurious `sat`).
    fp_class_markers: BTreeMap<AstId, (alloc::string::String, AstId)>,
    /// Uninterpreted `(default arr)` function decls, one per array sort, so a
    /// symbolic array's default value is congruent (`a = b ⇒ default a = default b`).
    array_default_decls: BTreeMap<AstId, AstId>,
    /// Opaque FP comparison-predicate markers (`fp.eq`/`fp.lt`/`fp.leq`/`fp.gt`/
    /// `fp.geq` whose operands could not be bit-blasted, e.g. `to_fp` conversions
    /// of symbolic reals/ints) -> (op name, lhs, rhs). Resolved once both operands
    /// are pinned to concrete FP constants (via `fold_fp_conversions`), so the
    /// predicate does not stay a free Boolean (a fuzz-found spurious `sat`).
    fp_cmp_markers: BTreeMap<AstId, (alloc::string::String, AstId, AstId)>,
    /// `((_ to_fp eb sb) x)` reinterpreting a symbolic width-(eb+sb) bit-vector `x`
    /// as an FP bit pattern: FP term → `(bv x, eb, sb)`. Lets `to_fp(x) = c` (c a
    /// concrete non-NaN FP) invert to `x = bits(c)`.
    fp_from_bv: BTreeMap<AstId, (AstId, u32, u32)>,
    /// Arithmetic pins `v = k` that `fold_fp_conversions` substituted away; the
    /// innermost `decide_inner` re-attaches the ones made during its run.
    fp_fold_pins: Vec<(AstId, AstId)>,
    /// The `RoundingMode` sort, once used.
    rm_sort: Option<AstId>,
    /// The five `RoundingMode` constants (RNE, RNA, RTP, RTN, RTZ), built with
    /// the sort.
    rm_modes: Vec<AstId>,
    /// Axioms valid in every model of their theory (the product sign and square
    /// rules): a decision procedure that cannot read one may ignore it without
    /// putting a `sat` at risk.
    valid_axioms: BTreeSet<AstId>,
    /// Floating-point constants: term → `(raw bits, eb, sb)`. Only `Float64`
    /// `(eb, sb) = (11, 53)` constants are folded (via `f64`); other formats and
    /// symbolic values are gated to a sound `unknown`.
    fp_of: BTreeMap<AstId, (u64, u32, u32)>,
    /// Interning of FP constants by their (canonical) value `(bits, eb, sb)` →
    /// term, so two equal-valued literals share one AstId. This keeps EUF
    /// congruence honest: `f(+oo)` parsed twice must be the same application.
    fp_const_cache: BTreeMap<(u64, u32, u32), AstId>,
    /// Bit-vector representation of a symbolic FP term (`fp_to_bv`), so equality
    /// and the classification predicates bit-blast through the QF_BV engine.
    fp_bv: BTreeMap<AstId, AstId>,
    /// Raw 3-bit image of each symbolic RoundingMode constant (z3's fpa2bv
    /// encoding: 0 RNE, 1 RNA, 2 RTP, 3 RTN, 4 RTZ; see [`Self::rm_bits`]).
    rm_bv: BTreeMap<AstId, AstId>,
    /// While `> 0` (parsing inside a quantifier body), FP operations are kept as
    /// opaque *deferred* symbolic nodes rather than bit-blasted eagerly. Mirrors
    /// z3's architecture: parsing keeps FP as symbolic theory terms and the
    /// `fpa2bv` conversion runs later, as a whole-goal pass — here `fpa_blast`,
    /// applied to each ground instance *after* quantifier instantiation. Eager
    /// parse-time blasting ties an FP op to a fresh bit-vector disconnected from
    /// the binder, so `substitute` cannot reach it (see the deferral in `fp_op`).
    fp_defer_depth: u32,
    /// Nesting depth of `try_disjunction_sat_witness`: a disjunct is itself a
    /// conjunction that may contain a disjunction, so re-entry is bounded.
    disj_witness_depth: u32,
    /// Set while `decide_independent_components` decides one component.
    in_components: bool,
    /// Set while [`Self::check_sat_components`] decides its groups.
    in_check_components: bool,
    /// `(as const …)` applications built so far in the current command.
    as_const_seen: u32,
    /// Set while `decide_by_guard_split` decides one case.
    in_guard_split: bool,
    /// Set while `decide_by_seq_length_split` decides one case.
    in_seq_len_split: bool,
    /// `:named` quantified assertions: (index into `universals`, name,
    /// `assertions.len()` when asserted).
    universal_names: Vec<(usize, String, usize)>,
    /// Whether the last check was `check-sat-using` with a macro-finder tactic.
    last_tactic_macro_finder: bool,
    /// Datalog relations (`declare-rel`) with their argument sorts.
    dl_rels: BTreeMap<String, Vec<SExpr>>,
    /// Datalog rule variables (`declare-var`).
    dl_vars: Vec<(String, SExpr)>,
    /// Cache of opaque FP-operation results by `(op, args)`, so a symbolic FP op
    /// is congruent — two occurrences with equal arguments share one term.
    fp_symbolic_cache: BTreeMap<(alloc::string::String, Vec<AstId>), AstId>,
    /// z3's unspecified `fp.to_ieee_bv` of NaN per `(eb, sb)` format: one
    /// fixed (unknown) NaN bit pattern, shared by every NaN argument.
    fp_ieee_nan: BTreeMap<(u32, u32), AstId>,
    /// `(fp.to_ieee_bv NaN)` display nodes → their [`Self::fp_ieee_nan`]
    /// value, substituted before solving and evaluation.
    fp_ieee_alias: BTreeMap<AstId, AstId>,
    /// z3's unspecified `fp.to_real` of NaN / `+oo` / `-oo` (class 0/1/2) per
    /// `(eb, sb)` format: one fixed (unknown) real each.
    fp_real_unspec: BTreeMap<(u32, u32, u8), AstId>,
    /// The last check's `purify-arith` sin/cos bases: `(θ, s, c)` with
    /// `sin θ ↦ s`, `cos θ ↦ c`; `θ`'s model value is rebuilt from `s`, `c`.
    trig_basis: Vec<(AstId, AstId, AstId)>,
    /// Each `(root-obj p i)` node → a real variable `r` and the axioms pinning
    /// it to that root: `p(r) = 0 ∧ lo < r < hi` over an isolating interval.
    root_obj_vars: BTreeMap<AstId, (AstId, Vec<AstId>)>,
    /// The interned per-`(op, domain)` declarations used for deferred FP nodes,
    /// so `fpa_blast` can recognise a deferred application and recover its op.
    fp_deferred_decls: BTreeSet<AstId>,
    /// `(op, domain sorts) → interned deferred decl`, so the same deferred FP op
    /// over the same argument sorts hash-conses to one application (a substituted
    /// instance stays congruent with the body it came from).
    fp_deferred_by_op: BTreeMap<(alloc::string::String, Vec<AstId>), AstId>,
    /// `(Seq E)` sorts, keyed by element sort.
    seq_sorts: BTreeMap<AstId, AstId>,
    /// Sequence terms with a known element list (built from `seq.unit`/`++`/
    /// `empty`), for structural folding of `seq.len`/`nth`/`at`/`extract`/`=`.
    seq_of: BTreeMap<AstId, Vec<AstId>>,
    /// Canonical empty sequence per sequence sort, so all `(as seq.empty S)`
    /// share one constant and `seq.len(s)=0 ⇒ s=empty` is enforceable.
    seq_empty: BTreeMap<AstId, AstId>,
    /// Symbolic divisor terms from `div`/`mod` (the non-numeral `b` in
    /// `div(a,b)`), collected during lifting so the SAT direction can witness by
    /// enumerating small divisor values.
    symbolic_divisors: BTreeSet<AstId>,
    /// Per symbolic-divisor `div`/`mod` abstraction: `(dividend, divisor, q, r)`
    /// where `q`/`r` are the fresh quotient/remainder. Lets the complete-UNSAT
    /// check reason about the constant-dividend class after lifting has replaced
    /// the div/mod terms with `q`/`r`.
    symbolic_divmod: Vec<(AstId, AstId, AstId, AstId)>,
    /// Per symbolic-divisor real `/` abstraction: `(dividend, divisor, q)` where
    /// `q` is the fresh real quotient. Lets a post-lift pass emit the exact-quotient
    /// identity `q = k` when the dividend is a product `d·k` and `d` is provably
    /// nonzero (`(/ (x·y) y) = x`).
    symbolic_realdiv: Vec<(AstId, AstId, AstId)>,
    /// Shared `Int → Int` uninterpreted functions for division/modulo by zero.
    /// SMT-LIB leaves `div a 0` / `mod a 0` unspecified, but z3 models them as
    /// `div0(a)` / `mod0(a)` — FUNCTIONS OF THE DIVIDEND — so all zero-divisor
    /// results with the same dividend agree (consistency). Created lazily.
    int_div0_decl: Option<AstId>,
    int_mod0_decl: Option<AstId>,
    /// Re-entrancy guard for `try_divmod_witness`: set while it recursively
    /// decides a divisor-concretised residual, so nested `decide_inner` calls do
    /// not re-enter the witness search (which would risk unbounded recursion).
    in_divmod_witness: bool,
    /// Re-entrancy guard for the opaque-atom strengthening in `decide`.
    in_opaque_strengthen: bool,
    /// Set while `decide` looks for a refutation of a goal with quantifier
    /// abstractions free (only its `unsat` is taken).
    in_quant_refute: bool,
    /// `seq.len` function declarations (one per element sort), tracked so a
    /// non-negativity axiom can be attached to each application.
    seq_len_decls: BTreeSet<AstId>,
    /// Symbolic `seq.++` markers with their parts, so the additive length axiom
    /// `len(s ++ t) = len(s) + len(t)` can be attached.
    seq_concat: Vec<(AstId, Vec<AstId>)>,
    /// Out-of-bounds `seq.nth` on a concrete sequence → a cached fresh free
    /// element (underspecified, matching z3), keyed by `(sequence, index)`.
    seq_nth_oob: BTreeMap<(AstId, i64), AstId>,
    /// Symbolic `seq.nth s i` markers, cached by `(s, i)` so repeated reads are
    /// the *same* term (congruent) — `nth s 0 = 1 ∧ nth s 0 = 2` then refutes.
    seq_nth_sym: BTreeMap<(AstId, AstId), AstId>,
    /// Symbolic `seq.at s i` markers, cached by `(s, i)` (congruent, like seq_nth_sym).
    seq_at_sym: BTreeMap<(AstId, AstId), AstId>,
    /// `seq.unit e` markers, cached by element so equal-element units are one term.
    seq_unit_cache: BTreeMap<AstId, AstId>,
    /// Symbolic `str.at x i` markers, cached by `(x, i)` so repeated reads at the
    /// same position are congruent — `str.at x i = "a" ∧ str.at x i = "b"` refutes.
    str_at_sym: BTreeMap<(AstId, AstId), AstId>,
    /// Symbolic `fp.roundToIntegral rm x` markers, cached by `(rm, x)` so two
    /// identical rounds are the same term (congruent). Needed for the idempotence
    /// refutation `roundToIntegral(rm, roundToIntegral(rm, x)) = roundToIntegral(rm, x)`
    /// when `rm` is symbolic (each `symbolic_fp` call is otherwise a fresh decl).
    fp_r2i_sym: BTreeMap<(AstId, AstId), AstId>,
    /// The operation name behind each symbolic sequence marker declaration, so a
    /// marker can be re-folded once its arguments become concrete (witness search).
    seqop_ops: BTreeMap<AstId, String>,
    /// The pre-axiom goal for the string/seq witness (set around `decide`), so the
    /// witness substitutes into a clean formula rather than the axiom-laden one.
    witness_base: Option<AstId>,
    /// Assumption literals of the most recent `(check-sat a …)` /
    /// `(check-sat-assuming (a …))`, as `(printed-text, term)` — the candidates
    /// an assumption-based `(get-unsat-core)` reports.
    last_assumptions: Vec<(String, AstId)>,
    /// Solver options set via `(set-option …)`, retrievable by `(get-option …)`.
    params: crate::util::Params,
    /// Uninterpreted sort *constructors* of arity ≥ 1 from `(declare-sort P n)`.
    /// Each application `(P s…)` monomorphizes to a distinct cached sort.
    sort_ctors: BTreeMap<String, usize>,
}

/// A constant regular expression (the decidable, fully-literal fragment). Used
/// to fold `(str.in_re "literal" r)` by matching.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum Regex {
    /// Matches exactly this code-point sequence (`str.to_re` of a literal).
    Lit(Vec<u32>),
    /// Any single code point in `[lo, hi]` (`re.range`).
    Range(u32, u32),
    /// Any single code point (`re.allchar`).
    AllChar,
    /// Every string (`re.all`).
    All,
    /// No string (`re.none`).
    None,
    Concat(Box<Regex>, Box<Regex>),
    Union(Box<Regex>, Box<Regex>),
    Inter(Box<Regex>, Box<Regex>),
    /// Complement (`re.comp`): every string the inner regex does *not* match.
    Comp(Box<Regex>),
    Star(Box<Regex>),
}

impl Regex {
    /// The literal words of `self` (`str.to_re` operands) and the bounds of
    /// its character ranges, as single-character words.
    fn literal_words(&self, out: &mut Vec<Vec<u32>>) {
        match self {
            Regex::Lit(l) => out.push(l.clone()),
            Regex::Range(lo, hi) => {
                out.push(alloc::vec![*lo]);
                out.push(alloc::vec![*hi]);
            }
            Regex::AllChar | Regex::All | Regex::None => {}
            Regex::Concat(a, b) | Regex::Union(a, b) | Regex::Inter(a, b) => {
                a.literal_words(out);
                b.literal_words(out);
            }
            Regex::Comp(a) | Regex::Star(a) => a.literal_words(out),
        }
    }

    /// The set of end positions after matching `self` in `s` starting at `from`.
    fn ends(&self, s: &[u32], from: usize) -> BTreeSet<usize> {
        let mut out = BTreeSet::new();
        match self {
            Regex::Lit(l) => {
                if from + l.len() <= s.len() && s[from..from + l.len()] == l[..] {
                    out.insert(from + l.len());
                }
            }
            Regex::Range(lo, hi) => {
                if from < s.len() && (*lo..=*hi).contains(&s[from]) {
                    out.insert(from + 1);
                }
            }
            Regex::AllChar => {
                if from < s.len() {
                    out.insert(from + 1);
                }
            }
            Regex::All => {
                for p in from..=s.len() {
                    out.insert(p);
                }
            }
            Regex::None => {}
            Regex::Concat(a, b) => {
                for mid in a.ends(s, from) {
                    out.extend(b.ends(s, mid));
                }
            }
            Regex::Union(a, b) => {
                out.extend(a.ends(s, from));
                out.extend(b.ends(s, from));
            }
            Regex::Inter(a, b) => {
                let ea = a.ends(s, from);
                for p in b.ends(s, from) {
                    if ea.contains(&p) {
                        out.insert(p);
                    }
                }
            }
            Regex::Comp(r) => {
                // s[from..p] matches the complement iff it does not match `r`.
                let er = r.ends(s, from);
                for p in from..=s.len() {
                    if !er.contains(&p) {
                        out.insert(p);
                    }
                }
            }
            Regex::Star(r) => {
                // Reachable end positions by repeating `r` zero or more times;
                // the visited set prevents looping on empty matches.
                out.insert(from);
                let mut frontier = alloc::vec![from];
                while let Some(p) = frontier.pop() {
                    for q in r.ends(s, p) {
                        if out.insert(q) {
                            frontier.push(q);
                        }
                    }
                }
            }
        }
        out
    }

    /// Does `self` match the whole string `s`?
    fn matches(&self, s: &[u32]) -> bool {
        self.ends(s, 0).contains(&s.len())
    }

    /// Collect intervals of single code points (`[lo, hi]`, clamped to
    /// `max_char`) that are *provably* accepted as length-1 words by `self`.
    ///
    /// This is deliberately a *lower bound* on the single-character language:
    /// only nodes whose length-1 acceptance set is exactly known contribute
    /// (`re.range`, `re.allchar`/`re.all`, a single-char literal, and unions of
    /// those). Every other node — `Concat`, `Inter`, `Comp`, `Star`, `None`,
    /// multi-char literals — contributes nothing, which can only *under*-report
    /// coverage. Callers may therefore soundly conclude "accepts every single
    /// character" from a positive coverage result, never the reverse.
    fn collect_single_char_intervals(&self, max_char: u32, out: &mut Vec<(u32, u32)>) {
        match self {
            Regex::Range(lo, hi) => out.push((*lo, (*hi).min(max_char))),
            Regex::AllChar | Regex::All => out.push((0, max_char)),
            Regex::Lit(l) if l.len() == 1 => out.push((l[0], l[0])),
            Regex::Union(a, b) => {
                a.collect_single_char_intervals(max_char, out);
                b.collect_single_char_intervals(max_char, out);
            }
            _ => {}
        }
    }

    /// Does `self` provably accept *every* single code point in the alphabet
    /// `[0, max_char]`? Sound (never a false positive) via
    /// [`Regex::collect_single_char_intervals`]. When true and `self` is the
    /// body of a `re.*`, that Kleene star matches Σ*: any string is a
    /// concatenation of length-1 words, each of which `self` accepts.
    fn accepts_all_single_chars(&self, max_char: u32) -> bool {
        let mut ivs: Vec<(u32, u32)> = Vec::new();
        self.collect_single_char_intervals(max_char, &mut ivs);
        ivs.sort_unstable();
        let mut next: u32 = 0;
        for (lo, hi) in ivs {
            if lo > next {
                return false;
            }
            if hi >= next {
                if hi >= max_char {
                    return true;
                }
                next = hi + 1;
            }
        }
        false
    }

    /// A literal operand of a (possibly nested) `re.inter` — the language is then a
    /// subset of `{that literal}`, so membership pins the word.
    fn inter_literal(&self) -> Option<Vec<u32>> {
        match self {
            Regex::Inter(a, b) => {
                if let Regex::Lit(l) = a.as_ref() {
                    Some(l.clone())
                } else if let Regex::Lit(l) = b.as_ref() {
                    Some(l.clone())
                } else {
                    a.inter_literal().or_else(|| b.inter_literal())
                }
            }
            _ => None,
        }
    }

    /// Does the language contain the empty string?
    fn nullable(&self) -> bool {
        match self {
            Regex::Lit(l) => l.is_empty(),
            Regex::Range(..) | Regex::AllChar | Regex::None => false,
            Regex::All | Regex::Star(_) => true,
            Regex::Concat(a, b) => a.nullable() && b.nullable(),
            Regex::Union(a, b) => a.nullable() || b.nullable(),
            Regex::Inter(a, b) => a.nullable() && b.nullable(),
            Regex::Comp(a) => !a.nullable(),
        }
    }

    /// A **sound over-approximation** of "some word in the language starts with
    /// code point `c`". Returns `false` only when *no* such word exists, so a
    /// caller may refute on `false` but must not conclude anything from `true`.
    /// (`Comp`/`Inter` are conservatively `true`/AND to stay sound.)
    fn can_start_with(&self, c: u32) -> bool {
        match self {
            Regex::Lit(l) => l.first() == Some(&c),
            Regex::Range(lo, hi) => (*lo..=*hi).contains(&c),
            Regex::AllChar | Regex::All => true,
            Regex::None => false,
            Regex::Concat(a, b) => a.can_start_with(c) || (a.nullable() && b.can_start_with(c)),
            Regex::Union(a, b) => a.can_start_with(c) || b.can_start_with(c),
            Regex::Inter(a, b) => a.can_start_with(c) && b.can_start_with(c),
            Regex::Star(a) => a.can_start_with(c),
            Regex::Comp(_) => true,
        }
    }

    /// Sound over-approximation of "some word in the language ends with code
    /// point `c`" (mirror of [`Regex::can_start_with`]).
    fn can_end_with(&self, c: u32) -> bool {
        match self {
            Regex::Lit(l) => l.last() == Some(&c),
            Regex::Range(lo, hi) => (*lo..=*hi).contains(&c),
            Regex::AllChar | Regex::All => true,
            Regex::None => false,
            Regex::Concat(a, b) => b.can_end_with(c) || (b.nullable() && a.can_end_with(c)),
            Regex::Union(a, b) => a.can_end_with(c) || b.can_end_with(c),
            Regex::Inter(a, b) => a.can_end_with(c) && b.can_end_with(c),
            Regex::Star(a) => a.can_end_with(c),
            Regex::Comp(_) => true,
        }
    }

    /// Sound over-approximation of "some word in the language contains code point
    /// `c`" (anywhere). Used to refute `x ∈ r ∧ contains x "…c…"` when `c` is
    /// outside the language's alphabet (`x ∈ (a|b)* ∧ contains x "c"`).
    fn can_contain(&self, c: u32) -> bool {
        match self {
            Regex::Lit(l) => l.contains(&c),
            Regex::Range(lo, hi) => (*lo..=*hi).contains(&c),
            Regex::AllChar | Regex::All => true,
            Regex::None => false,
            Regex::Concat(a, b) | Regex::Union(a, b) => a.can_contain(c) || b.can_contain(c),
            Regex::Inter(a, b) => a.can_contain(c) && b.can_contain(c),
            Regex::Star(a) => a.can_contain(c),
            Regex::Comp(_) => true,
        }
    }

    /// The set of code points a matching word can *start* with, as sorted
    /// inclusive ranges — `None` when it can't be bounded (`AllChar`/`Comp`, or an
    /// `Inter` we don't intersect exactly). Used to detect an empty `re.inter`.
    fn first_ranges(&self) -> Option<Vec<(u32, u32)>> {
        match self {
            Regex::Lit(l) => Some(l.first().map(|&c| alloc::vec![(c, c)]).unwrap_or_default()),
            Regex::Range(lo, hi) => Some(alloc::vec![(*lo, *hi)]),
            Regex::None => Some(Vec::new()),
            Regex::AllChar | Regex::All | Regex::Comp(_) => None,
            Regex::Union(a, b) => {
                let mut r = a.first_ranges()?;
                r.extend(b.first_ranges()?);
                Some(r)
            }
            Regex::Concat(a, b) => {
                let mut r = a.first_ranges()?;
                if a.nullable() {
                    r.extend(b.first_ranges()?);
                }
                Some(r)
            }
            Regex::Star(a) => a.first_ranges(),
            Regex::Inter(_, _) => None,
        }
    }

    /// Whether the language is provably empty (sound: only a definite `true`).
    /// Covers `re.inter` of two non-nullable parts whose first-character sets are
    /// disjoint (`(a-z)+ ∩ (0-9)+`).
    fn is_empty_lang(&self) -> bool {
        if let Regex::Inter(a, b) = self {
            // Disjoint first-character sets (both non-nullable).
            if !a.nullable()
                && !b.nullable()
                && let (Some(ra), Some(rb)) = (a.first_ranges(), b.first_ranges())
                && ra
                    .iter()
                    .all(|&(al, ah)| rb.iter().all(|&(bl, bh)| ah < bl || bh < al))
            {
                return true;
            }
            // Disjoint length sets (`"abc" ∩ (a-z)(a-z)`: only-len-3 ∩ only-len-2).
            const M: usize = 32;
            if let (Some(la), Some(lb)) = (a.lengths(M), b.lengths(M))
                && (0..=M).all(|n| !(la.get(n) == Some(&true) && lb.get(n) == Some(&true)))
            {
                return true;
            }
        }
        if matches!(self, Regex::None) {
            return true;
        }
        // General decision: explore the Brzozowski-derivative automaton. This is
        // exact for the full algebra (including `Comp`/`Inter`), so a definite
        // `Some(true)` is a sound emptiness proof; `None` (state budget exceeded)
        // falls back to "not proven empty".
        self.language_is_empty() == Some(true)
    }

    /// Collect the interval cut points induced by the literals and ranges in this
    /// regex, so a representative code point per behaviour class can be chosen for
    /// the derivative automaton.
    fn collect_cuts(&self, cuts: &mut BTreeSet<u32>) {
        match self {
            Regex::Lit(l) => {
                for &x in l {
                    cuts.insert(x);
                    if x < SMT_MAX_CODE_POINT {
                        cuts.insert(x + 1);
                    }
                }
            }
            Regex::Range(lo, hi) => {
                cuts.insert(*lo);
                if *hi < SMT_MAX_CODE_POINT {
                    cuts.insert(hi + 1);
                }
            }
            Regex::AllChar | Regex::All | Regex::None => {}
            Regex::Concat(a, b) | Regex::Union(a, b) | Regex::Inter(a, b) => {
                a.collect_cuts(cuts);
                b.collect_cuts(cuts);
            }
            Regex::Comp(a) | Regex::Star(a) => a.collect_cuts(cuts),
        }
    }

    /// The Brzozowski derivative of the language with respect to code point `c`:
    /// the set of words `w` such that `c·w` is in `L(self)`.
    fn derivative(&self, c: u32) -> Regex {
        match self {
            Regex::Lit(l) => match l.split_first() {
                Some((&x, rest)) if x == c => Regex::Lit(rest.to_vec()),
                _ => Regex::None,
            },
            Regex::Range(lo, hi) => {
                if (*lo..=*hi).contains(&c) {
                    Regex::Lit(Vec::new())
                } else {
                    Regex::None
                }
            }
            Regex::AllChar => Regex::Lit(Vec::new()),
            Regex::All => Regex::All,
            Regex::None => Regex::None,
            Regex::Concat(a, b) => {
                let da = Regex::Concat(Box::new(a.derivative(c)), b.clone());
                if a.nullable() {
                    Regex::Union(Box::new(da), Box::new(b.derivative(c)))
                } else {
                    da
                }
            }
            Regex::Union(a, b) => {
                Regex::Union(Box::new(a.derivative(c)), Box::new(b.derivative(c)))
            }
            Regex::Inter(a, b) => {
                Regex::Inter(Box::new(a.derivative(c)), Box::new(b.derivative(c)))
            }
            Regex::Comp(a) => Regex::Comp(Box::new(a.derivative(c))),
            Regex::Star(a) => {
                Regex::Concat(Box::new(a.derivative(c)), Box::new(Regex::Star(a.clone())))
            }
        }
    }

    /// A canonical form (union/intersection treated as ACI sets, epsilon/`None`
    /// units folded, double complement/star collapsed). Keeps the derivative
    /// state set finite so the automaton exploration terminates.
    fn normalize(&self) -> Regex {
        match self {
            Regex::Lit(_) | Regex::Range(..) | Regex::AllChar | Regex::All | Regex::None => {
                self.clone()
            }
            Regex::Concat(a, b) => {
                // Flatten and drop epsilon; any `None` factor annihilates.
                let mut factors: Vec<Regex> = Vec::new();
                for part in [a.normalize(), b.normalize()] {
                    let mut stack = alloc::vec![part];
                    while let Some(p) = stack.pop() {
                        match p {
                            Regex::Concat(x, y) => {
                                // preserve order: push y then x so x is processed first
                                stack.push(*y);
                                stack.push(*x);
                            }
                            other => factors.push(other),
                        }
                    }
                }
                if factors.iter().any(|f| matches!(f, Regex::None)) {
                    return Regex::None;
                }
                // Merge adjacent literals and drop epsilons.
                let mut merged: Vec<Regex> = Vec::new();
                for f in factors {
                    if let Regex::Lit(l) = &f {
                        if l.is_empty() {
                            continue;
                        }
                        if let Some(Regex::Lit(prev)) = merged.last_mut() {
                            prev.extend_from_slice(l);
                            continue;
                        }
                    }
                    merged.push(f);
                }
                match merged.len() {
                    0 => Regex::Lit(Vec::new()),
                    1 => merged.pop().unwrap(),
                    _ => {
                        let mut it = merged.into_iter().rev();
                        let mut acc = it.next().unwrap();
                        for f in it {
                            acc = Regex::Concat(Box::new(f), Box::new(acc));
                        }
                        acc
                    }
                }
            }
            Regex::Union(a, b) => {
                // Flatten structurally first (never re-normalise a `Union` node,
                // which would recurse into this same arm), then normalise leaves.
                let mut set: BTreeSet<Regex> = BTreeSet::new();
                let mut stack = alloc::vec![a.as_ref().clone(), b.as_ref().clone()];
                while let Some(p) = stack.pop() {
                    match p {
                        Regex::Union(x, y) => {
                            stack.push(*x);
                            stack.push(*y);
                        }
                        other => match other.normalize() {
                            Regex::Union(x, y) => {
                                stack.push(*x);
                                stack.push(*y);
                            }
                            Regex::None => {}
                            Regex::All => return Regex::All,
                            n => {
                                set.insert(n);
                            }
                        },
                    }
                }
                if set.is_empty() {
                    return Regex::None;
                }
                let mut it = set.into_iter();
                let mut acc = it.next().unwrap();
                for r in it {
                    acc = Regex::Union(Box::new(acc), Box::new(r));
                }
                acc
            }
            Regex::Inter(a, b) => {
                let mut set: BTreeSet<Regex> = BTreeSet::new();
                let mut stack = alloc::vec![a.as_ref().clone(), b.as_ref().clone()];
                while let Some(p) = stack.pop() {
                    match p {
                        Regex::Inter(x, y) => {
                            stack.push(*x);
                            stack.push(*y);
                        }
                        other => match other.normalize() {
                            Regex::Inter(x, y) => {
                                stack.push(*x);
                                stack.push(*y);
                            }
                            Regex::All => {}
                            Regex::None => return Regex::None,
                            n => {
                                set.insert(n);
                            }
                        },
                    }
                }
                match set.len() {
                    0 => Regex::All,
                    _ => {
                        let mut it = set.into_iter();
                        let mut acc = it.next().unwrap();
                        for r in it {
                            acc = Regex::Inter(Box::new(acc), Box::new(r));
                        }
                        acc
                    }
                }
            }
            Regex::Comp(a) => match a.normalize() {
                Regex::Comp(inner) => *inner,
                Regex::None => Regex::All,
                Regex::All => Regex::None,
                other => Regex::Comp(Box::new(other)),
            },
            Regex::Star(a) => match a.normalize() {
                Regex::Star(inner) => Regex::Star(inner),
                Regex::None => Regex::Lit(Vec::new()),
                Regex::Lit(l) if l.is_empty() => Regex::Lit(Vec::new()),
                Regex::All => Regex::All,
                other => Regex::Star(Box::new(other)),
            },
        }
    }

    /// Decide whether the language is empty by exploring the derivative
    /// automaton. `Some(true)`/`Some(false)` are exact; `None` means the state
    /// budget was exceeded (caller must not conclude anything).
    fn language_is_empty(&self) -> Option<bool> {
        const STATE_BUDGET: usize = 4000;
        let mut cuts: BTreeSet<u32> = BTreeSet::new();
        cuts.insert(0);
        self.collect_cuts(&mut cuts);
        let reps: Vec<u32> = cuts.into_iter().collect();
        let start = self.normalize();
        if start.nullable() {
            return Some(false);
        }
        let mut visited: BTreeSet<Regex> = BTreeSet::new();
        visited.insert(start.clone());
        let mut frontier = alloc::vec![start];
        while let Some(r) = frontier.pop() {
            for &c in &reps {
                let d = r.derivative(c).normalize();
                if d.nullable() {
                    return Some(false);
                }
                if visited.insert(d.clone()) {
                    if visited.len() > STATE_BUDGET {
                        return None;
                    }
                    frontier.push(d);
                }
            }
        }
        Some(true)
    }

    /// Decide language equivalence with `other` via emptiness of the symmetric
    /// difference. `None` when undecided (state budget exceeded).
    fn equivalent(&self, other: &Regex) -> Option<bool> {
        let symdiff = Regex::Union(
            Box::new(Regex::Inter(
                Box::new(self.clone()),
                Box::new(Regex::Comp(Box::new(other.clone()))),
            )),
            Box::new(Regex::Inter(
                Box::new(Regex::Comp(Box::new(self.clone()))),
                Box::new(other.clone()),
            )),
        );
        symdiff.language_is_empty()
    }

    /// Whether the language contains no *non-empty* word (it may contain `""`).
    /// Sound: only a definite `true`. Covers `re.inter` of two parts with disjoint
    /// first-character sets (`(a-m)* ∩ (n-z)*` matches only `""`).
    fn nonempty_impossible(&self) -> bool {
        match self {
            Regex::None => true,
            Regex::Lit(l) => l.is_empty(),
            Regex::Inter(a, b) => {
                if let (Some(ra), Some(rb)) = (a.first_ranges(), b.first_ranges()) {
                    ra.iter()
                        .all(|&(al, ah)| rb.iter().all(|&(bl, bh)| ah < bl || bh < al))
                } else {
                    false
                }
            }
            Regex::Star(a) => a.nonempty_impossible(),
            _ => false,
        }
    }

    /// The longest literal every matching word must start with (sound: a definite
    /// lower bound). `re.++ "http" (a-z)*` ⇒ `"http"`.
    fn mandatory_prefix(&self) -> Vec<u32> {
        match self {
            Regex::Lit(l) => l.clone(),
            Regex::Range(lo, hi) if lo == hi => alloc::vec![*lo],
            Regex::Concat(a, b) => {
                let mut p = a.mandatory_prefix();
                // Only extend past `a` if `a` matches exactly one word (a fixed
                // literal), so its prefix is the whole of `a`.
                if let Regex::Lit(la) = a.as_ref()
                    && *la == p
                {
                    p.extend(b.mandatory_prefix());
                }
                p
            }
            Regex::Inter(a, b) => {
                let (pa, pb) = (a.mandatory_prefix(), b.mandatory_prefix());
                if pa.len() >= pb.len() { pa } else { pb }
            }
            _ => Vec::new(),
        }
    }

    /// The longest literal every matching word must end with (mirror of
    /// `mandatory_prefix`). `re.++ (a-z) "xyz"` ⇒ `"xyz"`.
    fn mandatory_suffix(&self) -> Vec<u32> {
        match self {
            Regex::Lit(l) => l.clone(),
            Regex::Range(lo, hi) if lo == hi => alloc::vec![*lo],
            Regex::Concat(a, b) => {
                let mut s = b.mandatory_suffix();
                // Extend backwards past `b` only if `b` is a fixed literal.
                if let Regex::Lit(lb) = b.as_ref()
                    && *lb == s
                {
                    let mut p = a.mandatory_suffix();
                    p.extend(s);
                    s = p;
                }
                s
            }
            Regex::Inter(a, b) => {
                let (sa, sb) = (a.mandatory_suffix(), b.mandatory_suffix());
                if sa.len() >= sb.len() { sa } else { sb }
            }
            _ => Vec::new(),
        }
    }

    /// The complete finite set of words in the language, or `None` if it is
    /// infinite or exceeds `budget` words. `("yes" | "no")` ⇒ `{yes, no}`.
    fn all_words(&self, budget: usize) -> Option<Vec<Vec<u32>>> {
        let out = match self {
            Regex::None => Vec::new(),
            Regex::Lit(l) => alloc::vec![l.clone()],
            Regex::Range(lo, hi) => {
                if (*hi as usize).saturating_sub(*lo as usize) >= budget {
                    return None;
                }
                (*lo..=*hi).map(|c| alloc::vec![c]).collect()
            }
            Regex::Union(a, b) => {
                let mut w = a.all_words(budget)?;
                w.extend(b.all_words(budget)?);
                w
            }
            Regex::Concat(a, b) => {
                let (wa, wb) = (a.all_words(budget)?, b.all_words(budget)?);
                if wa.len().checked_mul(wb.len())? > budget {
                    return None;
                }
                let mut w = Vec::new();
                for x in &wa {
                    for y in &wb {
                        let mut c = x.clone();
                        c.extend_from_slice(y);
                        w.push(c);
                    }
                }
                w
            }
            _ => return None, // Star/All/AllChar/Inter/Comp: infinite or opaque
        };
        if out.len() > budget {
            return None;
        }
        Some(out)
    }

    /// Every word of *exactly* length `n` (finite even through `Star`, since the
    /// length is bounded). `None` if the alphabet is too wide (`AllChar`/`All`) or
    /// the count exceeds `cap`, or the language is opaque (`Inter`/`Comp`).
    fn words_of_length(&self, n: usize, cap: usize) -> Option<Vec<Vec<u32>>> {
        let out = match self {
            Regex::None => Vec::new(),
            Regex::Lit(l) => {
                if l.len() == n {
                    alloc::vec![l.clone()]
                } else {
                    Vec::new()
                }
            }
            Regex::Range(lo, hi) => {
                if n != 1 {
                    Vec::new()
                } else if (*hi as usize).saturating_sub(*lo as usize) >= cap {
                    return None;
                } else {
                    (*lo..=*hi).map(|c| alloc::vec![c]).collect()
                }
            }
            Regex::Union(a, b) => {
                let mut w = a.words_of_length(n, cap)?;
                w.extend(b.words_of_length(n, cap)?);
                w
            }
            Regex::Concat(a, b) => {
                let mut w = Vec::new();
                for i in 0..=n {
                    let wa = a.words_of_length(i, cap)?;
                    if wa.is_empty() {
                        continue;
                    }
                    let wb = b.words_of_length(n - i, cap)?;
                    for x in &wa {
                        for y in &wb {
                            let mut c = x.clone();
                            c.extend_from_slice(y);
                            w.push(c);
                            if w.len() > cap {
                                return None;
                            }
                        }
                    }
                }
                w
            }
            Regex::Star(r) => {
                if n == 0 {
                    alloc::vec![Vec::new()]
                } else {
                    let mut w = Vec::new();
                    for i in 1..=n {
                        let wr = r.words_of_length(i, cap)?;
                        if wr.is_empty() {
                            continue;
                        }
                        let rest = self.words_of_length(n - i, cap)?; // Star of the remainder
                        for x in &wr {
                            for y in &rest {
                                let mut c = x.clone();
                                c.extend_from_slice(y);
                                w.push(c);
                                if w.len() > cap {
                                    return None;
                                }
                            }
                        }
                    }
                    w.sort();
                    w.dedup();
                    w
                }
            }
            _ => return None, // AllChar/All/Inter/Comp
        };
        if out.len() > cap {
            return None;
        }
        Some(out)
    }

    /// Whether every character of every word is an ASCII digit `'0'..='9'`
    /// (sound: only a definite `true`). A non-empty such word is numeric, so
    /// `str.to_int` of it is ≥ 0.
    fn only_digits(&self) -> bool {
        let (d0, d9) = ('0' as u32, '9' as u32);
        match self {
            Regex::Lit(l) => l.iter().all(|&c| (d0..=d9).contains(&c)),
            Regex::Range(lo, hi) => *lo >= d0 && *hi <= d9,
            Regex::None => true,
            Regex::Concat(a, b) | Regex::Union(a, b) => a.only_digits() && b.only_digits(),
            Regex::Inter(a, b) => a.only_digits() || b.only_digits(),
            Regex::Star(a) => a.only_digits(),
            _ => false,
        }
    }

    /// Which lengths `0..=max` a matching word can have — *exact* for the
    /// supported constructors. `None` when the length set cannot be computed
    /// exactly (`re.inter`/`re.comp`), so callers fall back to a sound `unknown`.
    fn lengths(&self, max: usize) -> Option<Vec<bool>> {
        let mut v = alloc::vec![false; max + 1];
        match self {
            Regex::Lit(l) => {
                if l.len() <= max {
                    v[l.len()] = true;
                }
            }
            Regex::Range(_, _) | Regex::AllChar => {
                if max >= 1 {
                    v[1] = true;
                }
            }
            Regex::All => v.iter_mut().for_each(|b| *b = true),
            Regex::None => {}
            Regex::Concat(a, b) => {
                let (la, lb) = (a.lengths(max)?, b.lengths(max)?);
                for i in 0..=max {
                    if la[i] {
                        for j in 0..=(max - i) {
                            if lb[j] {
                                v[i + j] = true;
                            }
                        }
                    }
                }
            }
            Regex::Union(a, b) => {
                let (la, lb) = (a.lengths(max)?, b.lengths(max)?);
                for i in 0..=max {
                    v[i] = la[i] || lb[i];
                }
            }
            Regex::Star(a) => {
                let la = a.lengths(max)?;
                v[0] = true;
                for i in 0..=max {
                    if v[i] {
                        for u in 1..=(max - i) {
                            if la[u] {
                                v[i + u] = true;
                            }
                        }
                    }
                }
            }
            Regex::Inter(a, b) => {
                // `lengths(A ∩ B) ⊆ lengths(A) ∩ lengths(B)` — a string of length k
                // in the intersection is in both, so the set-intersection is a sound
                // over-approximation (an unknown side is "all lengths").
                match (a.lengths(max), b.lengths(max)) {
                    (Some(la), Some(lb)) => {
                        for i in 0..=max {
                            v[i] = la[i] && lb[i];
                        }
                    }
                    (Some(la), None) => v = la,
                    (None, Some(lb)) => v = lb,
                    (None, None) => return None,
                }
            }
            Regex::Comp(_) => return None,
        }
        Some(v)
    }

    /// An upper bound on the length of the words of `self`, or `None` when
    /// they are unbounded (or the bound is unknown).
    fn max_len(&self) -> Option<usize> {
        match self {
            Regex::Lit(l) => Some(l.len()),
            Regex::Range(_, _) | Regex::AllChar => Some(1),
            Regex::None => Some(0),
            Regex::All | Regex::Comp(_) => None,
            Regex::Concat(a, b) => Some(a.max_len()? + b.max_len()?),
            Regex::Union(a, b) => Some(a.max_len()?.max(b.max_len()?)),
            Regex::Inter(a, b) => match (a.max_len(), b.max_len()) {
                (Some(x), Some(y)) => Some(x.min(y)),
                (x, y) => x.or(y),
            },
            Regex::Star(a) => (a.max_len()? == 0).then_some(0),
        }
    }
}

