    #[test]
    fn string_index_witnesses_are_folded_and_modelled() {
        // Fuzz-found: `str.at "aab" i` with `i = 0` inlined became a fresh
        // marker the opaque gate missed (wrong sat), and the witness search
        // left the enumerated `i` out of the model.
        let script = "
            (declare-const i Int)
            (declare-const s String)
            (assert (= s (str.at \"aab\" i)))
            (assert (<= (str.len s) i))
            (assert (= i 0))
            (check-sat)
            (reset)
            (declare-const i Int)
            (assert (<= (str.len (str.at \"aab\" i)) i))
            (check-sat)
            (get-model)
        ";
        let out = run(script).unwrap();
        assert_eq!(out[0], "unsat");
        assert_eq!(out[1], "sat");
        assert!(!out[2].contains("    0)"), "{}", out[2]);
    }

    #[test]
    fn literal_reads_at_symbolic_positions_case_split() {
        // z3 regression string6: `str.at "A" i` is "A" or "", and
        // `indexof "a" s` over a one-character `s` is 0 or -1.
        let script = "
            (declare-const s String)
            (declare-const s2 String)
            (declare-const i Int)
            (assert (= (str.len s) 1))
            (assert (= (str.indexof \"a\" s) i))
            (assert (or (and (= s s2) (< i 0)) (and (= (str.at \"A\" i) s2) (>= i 0))))
            (assert (= s2 \"a\"))
            (check-sat)
        ";
        assert_eq!(run(script).unwrap(), alloc::vec!["unsat"]);
    }

