    #[test]
    fn string_witness_derives_producer_bound_variables() {
        // z3 regressions issue-1841 / 3105: `src` is computed from its producer
        // rather than enumerated, and a symbolic-length `substr` gets its
        // clamped-length axioms (so the length hint is `len a ≥ 4`).
        let script = "
            (declare-fun str0 () String)
            (declare-fun str1 () String)
            (declare-fun str2 () String)
            (declare-fun src () String)
            (declare-fun dst () String)
            (declare-fun s () String)
            (declare-const i Int)
            (assert (= src (str.at (str.replace str0 str1 str2) i)))
            (assert (= (str.replace s src dst) \"a\"))
            (check-sat)
            (reset)
            (declare-fun a () String)
            (declare-fun b () String)
            (declare-fun c () String)
            (assert (distinct (str.substr a 3 (str.len b)) \"\"))
            (assert (distinct
                     (ite (= (str.len (str.substr (str.replace a b \"\") 0 (- (str.len c)))) 1) 0 2)
                     (ite (= (str.at (str.replace a b \"\") 2) \"\") 1 2)))
            (check-sat)
            (reset)
            (declare-const a String)
            (declare-const b String)
            (declare-const i Int)
            (assert (= (str.len (str.substr (str.++ \"aab\" a) i 1)) i))
            (assert (distinct (str.++ a b) (str.substr \"aab\" i 1)))
            (check-sat)
            (get-value (i))
        ";
        let out = run(script).unwrap();
        assert_eq!(out[0], "sat");
        assert_eq!(out[1], "sat");
        // Fuzz-found: a refolded string `ite` under `str.len` was read as a free
        // term (`i = 3` with `len(substr "aabc" 3 1) = 1`); now lifted.
        if out[2] == "sat" {
            assert_ne!(out[3], "((i 3))");
        }
    }

    #[test]
    fn string_witness_coordinate_search_and_preprocessing_tactics() {
        // z3 regression 2478 (reduced): three independently constrained
        // variables whose witnesses lie far apart in the candidate product.
        let script = "
            (declare-fun f () String)
            (declare-fun g () String)
            (declare-fun s () String)
            (declare-fun c () String)
            (declare-fun b () String)
            (assert (not (= \"\" g)))
            (assert (= (str.replace g \"Pkgwt\" \"\") \"Example:\"))
            (assert (not (= (str.len f) 0)))
            (assert (not (str.contains f \"E\")))
            (assert (= (str.indexof s \"=\" 0) 0))
            (assert (= c (str.++ f g)))
            (assert (= b (str.++ s g)))
            (check-sat)
            (reset)
            (declare-fun a () Int)
            (assert (distinct a (str.to.int (int.to.str a))))
            (check-sat-using fix-dl-var)
        ";
        let out = run(script).unwrap();
        assert_eq!(out, alloc::vec!["sat", "unknown"]);
    }

    #[test]
    fn string_containment_orders_and_symbolic_at() {
        // z3 regression string-ops: transitivity, substrings of a literal,
        // `str.at` out of range, a found needle filling the word, and the
        // generic `seq.*` operations over a `String`.
        let script = "
            (declare-const a String)
            (declare-const b String)
            (declare-const c String)
            (declare-const i Int)
            (push)
            (assert (str.contains a b))
            (assert (str.contains b c))
            (assert (not (str.contains a c)))
            (check-sat)
            (pop)
            (push)
            (assert (str.suffixof a b))
            (assert (str.suffixof b c))
            (assert (not (str.suffixof a c)))
            (check-sat)
            (pop)
            (push)
            (assert (str.contains \"abc\" a))
            (assert (str.contains \"def\" a))
            (assert (not (= a \"\")))
            (check-sat)
            (pop)
            (push)
            (assert (< i 0))
            (assert (= \"b\" (str.at a i)))
            (check-sat)
            (pop)
            (push)
            (assert (= (str.len a) (+ 3 (str.indexof a \"abc\"))))
            (assert (= (str.len a) 3))
            (assert (not (= a \"abc\")))
            (check-sat)
            (pop)
            (push)
            (assert (= (seq.len a) 2))
            (assert (= b (seq.at a 0)))
            (assert (= b (seq.at a 1)))
            (check-sat)
            (pop)
            (push)
            (assert (str.prefixof \"\" (str.replace \"\" b a)))
            (check-sat)
            (pop)
        ";
        let out = run(script).unwrap();
        assert_eq!(
            out,
            alloc::vec!["unsat", "unsat", "unsat", "unsat", "unsat", "sat", "sat"]
        );
    }

    #[test]
    fn higher_order_sequence_operations() {
        // z3 regressions testmap / testmapi / testfoldl: z3's rewrites print
        // in its syntax, and goals over a sequence variable are witnessed by
        // short concrete sequences (with congruence of `p` by content).
        let script = "
            (declare-const f (Array Int Int Int))
            (declare-const g (Array Int Bool Int Bool))
            (declare-const il_1 (Seq Int))
            (declare-const il_2 (Seq Int))
            (declare-const i Int)
            (simplify (seq.foldl f 2 (seq.++ il_1 il_2)))
            (simplify (seq.foldli g 3 true (seq.unit i)))
            (simplify (seq.mapi f 2 (seq.++ il_1 il_2)))
            (simplify (seq.map (select f 1) (as seq.empty (Seq Int))))
            (reset)
            (declare-fun f (Int) Bool)
            (declare-fun p ((Seq Bool)) Bool)
            (declare-const il (Seq Int))
            (assert (p (seq.map f il)))
            (assert (not (p (seq.unit false))))
            (assert (not (p (seq.unit true))))
            (assert (not (= il (as seq.empty (Seq Int)))))
            (check-sat)
            (eval (>= (seq.len il) 2))
            (reset)
            (declare-const il (Seq Int))
            (declare-const F (Array Int Bool Int Bool))
            (assert (= (seq.foldli F 5 true il) true))
            (assert (> (seq.len il) 0))
            (assert (not (= F ((as const (Array Int Bool Int Bool)) true))))
            (check-sat)
        ";
        let out = run(script).unwrap();
        assert_eq!(
            out,
            alloc::vec![
                "(seq.fold_left f (seq.fold_left f 2 il_1) il_2)",
                "(select g 3 true i)",
                "(seq.++ (seq.mapi f 2 il_1) (seq.mapi f (+ 2 (seq.len il_1)) il_2))",
                "(as seq.empty (Seq Int))",
                "sat",
                "true",
                "sat",
            ]
        );
    }

